/* ===== 01-tokens.css ===== */
/* Split from styles.css lines 1-32 — @font-face + :root. Do not reorder relative to other 0N-*.css files. */
@font-face{
  font-family:"DirhamSymbol";
  src:url("fonts/AED.ttf") format("truetype");
  font-display:swap;
  unicode-range:U+007E;
}
@font-face{
  font-family:"RiyalSymbol";
  src:url("fonts/SAR.otf") format("opentype");
  font-display:swap;
  unicode-range:U+0024;
}

:root{
  --bg:#ffffff;
  --panel:rgba(255,255,255,.18);
  --panel-2:rgba(255,255,255,.10);
  --text:#17212b;
  --muted:#667085;
  --line:rgba(148,163,184,.18);
  --line-strong:rgba(100,116,139,.28);
  --primary:#2457d6;
  --primary-soft:rgba(36,87,214,.10);
  --success:#067647;
  --warning:#b54708;
  --danger:#b42318;
  --shadow:0 10px 28px rgba(16,24,40,.055);
  --shadow-strong:0 18px 42px rgba(16,24,40,.10);
  --radius:14px;
  --max:1240px;
  --content-max:1040px;
  --glass-blur:18px;
}


/* ===== 02-base.css ===== */
/* Split from styles.css lines 33-563 — body, layout primitives through before recycle bin. Do not reorder relative to other 0N-*.css files. */
*{box-sizing:border-box}
html,body{margin:0;padding:0}

body{
  font-family: "DirhamSymbol", "RiyalSymbol", Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background:var(--bg);
  color:var(--text);
  min-height:100vh;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
  position:relative;
}

.page-currency-bg{
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:0;
  overflow:hidden;
  contain:strict;
}
.float-currency{
  position:absolute;
  margin:0;
  font-weight:800;
  line-height:1;
  user-select:none;
  will-change:transform, opacity;
  transform:translate(-50%, -50%);
  animation-timing-function:ease-in-out;
  animation-iteration-count:infinite;
}
@media (prefers-reduced-motion: reduce){
  .float-currency{
    animation:none !important;
    opacity:.04 !important;
  }
}
.float-currency .symbol{
  display:inline-block;
  line-height:1;
}
.float-currency-aed .symbol-dirham{
  font-family:"DirhamSymbol", Inter, system-ui, sans-serif !important;
}
.float-currency-sar .symbol-riyal{
  font-family:"RiyalSymbol", Inter, system-ui, sans-serif !important;
}
.float-currency-pkr .symbol{
  font-family:Inter, system-ui, sans-serif;
  font-weight:750;
  letter-spacing:-0.02em;
}

@keyframes currency-float-path-1{
  0%,100%{transform:translate(-50%,-50%) translate(0,0) rotate(-8deg) scale(1);opacity:.035}
  12%{transform:translate(-50%,-50%) translate(6vw,-10vh) rotate(5deg) scale(1.04);opacity:.055}
  28%{transform:translate(-50%,-50%) translate(-8vw,4vh) rotate(-4deg) scale(.97);opacity:.045}
  44%{transform:translate(-50%,-50%) translate(10vw,8vh) rotate(6deg) scale(1.06);opacity:.065}
  61%{transform:translate(-50%,-50%) translate(-5vw,-12vh) rotate(-3deg) scale(1);opacity:.05}
  78%{transform:translate(-50%,-50%) translate(-12vw,6vh) rotate(4deg) scale(.98);opacity:.04}
}
@keyframes currency-float-path-2{
  0%,100%{transform:translate(-50%,-50%) translate(0,0) rotate(6deg) scale(1);opacity:.03}
  18%{transform:translate(-50%,-50%) translate(-10vw,12vh) rotate(-7deg) scale(1.08);opacity:.055}
  33%{transform:translate(-50%,-50%) translate(12vw,-5vh) rotate(5deg) scale(.95);opacity:.045}
  50%{transform:translate(-50%,-50%) translate(4vw,-14vh) rotate(-5deg) scale(1.03);opacity:.06}
  67%{transform:translate(-50%,-50%) translate(-7vw,9vh) rotate(8deg) scale(1);opacity:.04}
  84%{transform:translate(-50%,-50%) translate(8vw,5vh) rotate(-4deg) scale(1.05);opacity:.05}
}
@keyframes currency-float-path-3{
  0%,100%{transform:translate(-50%,-50%) translate(0,0) rotate(0deg) scale(1);opacity:.04}
  15%{transform:translate(-50%,-50%) translate(14vw,6vh) rotate(-9deg) scale(1.02);opacity:.06}
  30%{transform:translate(-50%,-50%) translate(-6vw,-11vh) rotate(7deg) scale(.96);opacity:.035}
  48%{transform:translate(-50%,-50%) translate(-14vw,3vh) rotate(-5deg) scale(1.07);opacity:.055}
  64%{transform:translate(-50%,-50%) translate(7vw,11vh) rotate(4deg) scale(.99);opacity:.045}
  82%{transform:translate(-50%,-50%) translate(3vw,-8vh) rotate(-6deg) scale(1.04);opacity:.05}
}
@keyframes currency-float-path-4{
  0%,100%{transform:translate(-50%,-50%) translate(0,0) rotate(-4deg) scale(1);opacity:.032}
  20%{transform:translate(-50%,-50%) translate(-9vw,-9vh) rotate(8deg) scale(1.05);opacity:.052}
  38%{transform:translate(-50%,-50%) translate(11vw,10vh) rotate(-6deg) scale(.94);opacity:.042}
  55%{transform:translate(-50%,-50%) translate(-4vw,14vh) rotate(5deg) scale(1.06);opacity:.058}
  72%{transform:translate(-50%,-50%) translate(9vw,-6vh) rotate(-7deg) scale(1);opacity:.038}
  88%{transform:translate(-50%,-50%) translate(-11vw,-4vh) rotate(3deg) scale(1.03);opacity:.048}
}

.shell{
  position:relative;
  z-index:1;
}
.site-footer{
  position:relative;
  /* Stay below .shell (z-index:1) so fixed overlays inside the app
     (e.g. trial-expired / guest-restriction) cover this footer. */
  z-index:0;
}
/* When workspace is locked (trial expired), keep footer out of the way of the dimmer. */
body.trial-locked .site-footer,
body.access-locked .site-footer{
  visibility:hidden;
  pointer-events:none;
}
button,input,select,textarea,option{
  font-family: inherit;
}

.symbol-dirham, .currency-chip .symbol-dirham { font-family: "DirhamSymbol", Inter, system-ui, sans-serif !important; }
.symbol-riyal, .currency-chip .symbol-riyal { font-family: "RiyalSymbol", Inter, system-ui, sans-serif !important; }
.symbol-dollar, .currency-chip .symbol-dollar { font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important; }
.currency-font-aed{font-family:"DirhamSymbol", Inter, system-ui, sans-serif !important;}
.currency-font-sar{font-family:"RiyalSymbol", Inter, system-ui, sans-serif !important;}
.currency-font-mixed{font-family:"RiyalSymbol", "DirhamSymbol", Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;}
.currency-font-usd,
.currency-font-normal{font-family:Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif !important;}

/* Ensure SAR symbol uses correct font in expense banners */
.expense-item-total .symbol-riyal,
.expense-transfer-totals .symbol-riyal,
.loan-name .symbol-riyal,
.loan-sub .symbol-riyal {
  font-family: "RiyalSymbol", Inter, system-ui, sans-serif !important;
}

a{color:inherit}

.shell{max-width:var(--max);margin:0 auto;padding:16px}

.header{
  display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;
  margin-bottom:14px;
}
.brand{display:flex;gap:16px;align-items:center;min-width:0;margin-bottom:24px;}
.mark{
  width:64px;height:64px;border-radius:16px;flex:0 0 auto;box-shadow:none;
  object-fit:contain;background:transparent;transition:transform 0.3s ease;
}
.mark:hover{
  transform:scale(1.05);
}

/* Main page logo styling for logo2.png (384x127 dimensions) */
.header .brand .mark[src*="logo2.png"] {
  width:180px;height:48px;border-radius:8px;
  object-fit:contain;
}
.brand h1{margin:0;font-size:1.18rem;line-height:1.2;letter-spacing:-.04em;font-weight:800;}
.brand p{margin:6px 0 0;color:var(--muted);font-size:.88rem;line-height:1.4;}
.chips{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}
.sr-only{
  position:absolute;
  width:1px;
  height:1px;
  padding:0;
  margin:-1px;
  overflow:hidden;
  clip:rect(0,0,0,0);
  white-space:nowrap;
  border:0;
}
.chip{
  border:1px solid var(--line);background:#fff;border-radius:999px;padding:7px 10px;font-size:.77rem;color:var(--muted);
  box-shadow:0 2px 10px rgba(16,24,40,.03);
}
.icon-chip{
  width:36px;height:36px;padding:0;
  display:grid;place-items:center;
  overflow:hidden;
}
.finance-chip{
  position:relative;
  isolation:isolate;
  background:linear-gradient(145deg,#f9fbff,#eef3ff);
  border-color:#dbe5ff;
}
.db-core,.db-ring,.cash-note,.cash-dot,.coin{
  position:absolute;
  display:block;
}
.db-core{
  width:12px;height:12px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#8cb0ff,#2457d6);
  box-shadow:0 0 0 3px rgba(36,87,214,.15);
  animation:pulse-core 1.8s ease-in-out infinite;
}
.db-ring{
  width:22px;height:22px;border-radius:50%;
  border:2px dashed rgba(36,87,214,.45);
  animation:spin-ring 3.5s linear infinite;
}
.cash-note{
  width:18px;height:12px;border-radius:4px;
  background:linear-gradient(135deg,#4caf7b,#1e8f5f);
  transform:rotate(-14deg);
  box-shadow:0 3px 6px rgba(30,143,95,.22);
  animation:float-cash 2s ease-in-out infinite;
}
.cash-dot{
  width:6px;height:6px;border-radius:50%;
  background:#d6ffe8;
  left:50%;top:50%;transform:translate(-50%,-50%);
}
.coin{
  width:13px;height:13px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#ffe79c,#f6ba2a);
  border:1px solid rgba(209,147,17,.45);
}
.coin-a{left:9px;top:12px;animation:bounce-coin 1.9s ease-in-out infinite}
.coin-b{left:16px;top:9px;animation:bounce-coin 1.9s ease-in-out infinite .2s}
@keyframes pulse-core{
  0%,100%{transform:scale(1)}
  50%{transform:scale(1.1)}
}
@keyframes spin-ring{to{transform:rotate(360deg)}}
@keyframes float-cash{
  0%,100%{transform:rotate(-14deg) translateY(0)}
  50%{transform:rotate(-14deg) translateY(-2px)}
}
@keyframes bounce-coin{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-2px)}
}
.chip-emoji{
  font-size:1.02rem;
  display:inline-block;
  animation:float-chip 1.9s ease-in-out infinite;
}
.icon-chip:nth-child(2) .chip-emoji{animation-delay:.2s}
.icon-chip:nth-child(3) .chip-emoji{animation-delay:.4s}
@keyframes float-chip{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(-2px)}
}

.overview{
  background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);
  padding:6px;margin-bottom:8px;
  width:100%;
  max-width:var(--content-max);
  margin-left:auto;
  margin-right:auto;
  box-sizing:border-box;
}
.overview-top{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:6px;padding:8px 12px;}
.overview-top h2,
.overview-top h3{margin:0;font-size:0.84rem;letter-spacing:-.03em}
.overview-top p{margin:2px 0 0;color:var(--muted);font-size:.72rem;line-height:1.35}
.overview-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px}
.summary{
  background:var(--panel-2);border:1px solid var(--line);border-radius:12px;padding:10px;min-height:72px;
  display:flex;flex-direction:column;justify-content:space-between;gap:6px;
}
.summary.currency-summary{
  position:relative;
  overflow:hidden;
}
.summary-watermark{
  position:absolute;
  inset:0;
  display:flex;
  align-items:center;
  justify-content:center;
  pointer-events:none;
  z-index:0;
  font-size:clamp(4.5rem, 28vw, 7.5rem);
  line-height:1;
  color:var(--text);
  opacity:.07;
  animation:summary-watermark-pulse 3.8s ease-in-out infinite;
}
.summary-watermark .symbol{
  font-size:1em;
  line-height:1;
}
.summary-watermark-goods{
  font-size:clamp(3.8rem, 24vw, 6.2rem);
  filter:grayscale(.15);
}
.summary-watermark-expense{
  flex-wrap:wrap;
  gap:1.2rem;
  padding:8%;
  animation:none;
  opacity:1;
}
.summary-watermark-expense .summary-watermark-symbol{
  position:relative;
  font-size:clamp(2.8rem, 16vw, 4.2rem);
  opacity:.06;
  animation:summary-watermark-pulse 3.6s ease-in-out infinite;
}
.summary-watermark-expense .summary-watermark-symbol .symbol{
  font-size:1em;
}

/* Floating wallet logos watermark (expense summary card) */
.wallet-float-watermark{
  position:absolute;
  inset:0;
  pointer-events:none;
  z-index:-1;
  overflow:hidden;
}
.wallet-float-watermark .wallet-float-logo{
  position:absolute;
  width:clamp(45px, 10vw, 70px);
  height:clamp(45px, 10vw, 70px);
  opacity:0;
  filter:grayscale(.12) brightness(1.08);
  will-change:transform, opacity;
  transform:translate3d(0,0,0) scale(var(--s, 1));
  animation:
    wallet-fade-in 0.8s ease-out forwards,
    wallet-drift-0 var(--d, 22s) ease-in-out calc(var(--delay, 0s) + 0.8s) infinite alternate;
}
@keyframes wallet-fade-in{
  from { opacity: 0; }
  to { opacity: .09; }
}
.wallet-float-watermark .wallet-float-logo img{
  width:100%;
  height:100%;
  object-fit:contain;
  display:block;
}
@keyframes wallet-drift-0{
  0%   { transform: translate(0px,    0px)    rotate(-8deg) scale(var(--s,1)); }
  25%  { transform: translate(80px,  -60px)   rotate(5deg)  scale(var(--s,1)); }
  50%  { transform: translate(-50px,  70px)   rotate(-4deg) scale(var(--s,1)); }
  75%  { transform: translate(70px,   -30px)  rotate(7deg)  scale(var(--s,1)); }
  100% { transform: translate(-40px, 50px)    rotate(-3deg) scale(var(--s,1)); }
}
@keyframes wallet-drift-1{
  0%   { transform: translate(0px,    0px)    rotate(10deg) scale(var(--s,1)); }
  25%  { transform: translate(-70px, 50px)   rotate(-6deg)  scale(var(--s,1)); }
  50%  { transform: translate(60px,  -40px)   rotate(8deg)  scale(var(--s,1)); }
  75%  { transform: translate(-50px,  -70px)   rotate(-5deg) scale(var(--s,1)); }
  100% { transform: translate(80px,  30px)    rotate(9deg)  scale(var(--s,1)); }
}
@keyframes wallet-drift-2{
  0%   { transform: translate(0px,    0px)    rotate(-12deg) scale(var(--s,1)); }
  25%  { transform: translate(50px,  80px)   rotate(6deg)  scale(var(--s,1)); }
  50%  { transform: translate(-60px, -50px)   rotate(-8deg) scale(var(--s,1)); }
  75%  { transform: translate(40px,   60px)   rotate(5deg)  scale(var(--s,1)); }
  100% { transform: translate(-70px, -40px)   rotate(-7deg) scale(var(--s,1)); }
}
@keyframes wallet-drift-3{
  0%   { transform: translate(0px,    0px)    rotate(5deg) scale(var(--s,1)); }
  25%  { transform: translate(-80px, -50px)  rotate(-9deg)  scale(var(--s,1)); }
  50%  { transform: translate(70px,  60px)   rotate(7deg)  scale(var(--s,1)); }
  75%  { transform: translate(-40px, -80px)   rotate(-6deg) scale(var(--s,1)); }
  100% { transform: translate(50px,  70px)    rotate(8deg)  scale(var(--s,1)); }
}
@keyframes wallet-zoom{
  0% { filter:grayscale(.12) brightness(1.0); opacity:.12; }
  100% { filter:grayscale(.05) brightness(1.15); opacity:.18; }
}

@keyframes wallet-rotate{
  0% { transform: translate(0px, 0px) rotate(-12deg) scale(var(--s,1)); }
  33% { transform: translate(8px, -15px) rotate(8deg) scale(var(--s,1)); }
  66% { transform: translate(-10px, 12px) rotate(-5deg) scale(var(--s,1)); }
  100% { transform: translate(6px, 8px) rotate(10deg) scale(var(--s,1)); }
}

/* Wallet logo watermark styling */
.summary-watermark img{
  max-width:80%;
  max-height:80%;
  object-fit:contain;
  opacity:0.45 !important;
  filter:grayscale(0.1) brightness(1.0);
  transition:opacity 0.3s ease;
}
@keyframes summary-watermark-pulse{
  0%,100%{transform:scale(.94);opacity:.40}
  50%{transform:scale(1.06);opacity:.50}
}
.summary .currency-head,
.summary-line-one{
  position:relative;
  z-index:1;
}
.summary span{font-size:.74rem;color:var(--muted)}
.summary strong{font-size:1rem;letter-spacing:-.02em}
.currency-summary{gap:7px}
.currency-head{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;font-size:2rem;line-height:1;}
.summary-line{
  display:flex;justify-content:space-between;gap:10px;align-items:baseline;
  font-size:.82rem;line-height:1.4;
}
.summary-line span{color:var(--muted)}
.summary-line strong{font-size:.84rem;white-space:nowrap}
.summary-line-one{
  display:flex;
  flex-direction:row;
  flex-wrap:nowrap;
  justify-content:space-between;
  align-items:baseline;
  gap:8px;
  width:100%;
  line-height:1.35;
}
.summary-line-one-label{
  flex:0 1 auto;
  color:var(--muted);
  font-size:.74rem;
  font-weight:650;
  white-space:nowrap;
}
.summary-line-one-value{
  flex:0 0 auto;
  min-width:0;
  text-align:right;
  font-size:.84rem;
  font-weight:700;
  color:var(--text);
}
.summary-line-one-value .money{
  font-size:inherit;
  font-weight:inherit;
}
.summary-line-one-value strong{
  font-size:inherit;
  white-space:nowrap;
}
.summary-line-one-label--with-symbol{
  display:inline-flex;
  align-items:baseline;
  gap:0.35em;
  flex-wrap:nowrap;
  max-width:100%;
}
.summary-currency-mark{
  display:inline-flex;
  align-items:baseline;
  flex-shrink:0;
  line-height:1;
}
.summary-currency-mark .symbol{
  font-size:1.08em;
  line-height:1;
}
.summary-label-suffix{
  color:var(--muted);
  font-weight:650;
}

.tabs{
  display:flex;gap:6px;flex-wrap:wrap;justify-content:center;align-items:center;background:#fff;border:1px solid var(--line);border-radius:14px;padding:5px 10px;
  margin-bottom:14px;box-shadow:var(--shadow);position:sticky;top:12px;z-index:20;
  width:100%;
  max-width:none;
  margin-left:0;
  margin-right:0;
  box-sizing:border-box;
}
@media (min-width: 821px){
  .tabs{
    padding:6px 10px;
    gap:8px;
    justify-content:space-between;
    flex-wrap:nowrap;
  }
  .tabs > .tab:not(.hide){
    flex:1 1 0;
    min-width:0;
    max-width:100%;
    box-sizing:border-box;
    text-align:center;
    justify-content:center;
    display:inline-flex;
    align-items:center;
    gap:5px;
    padding:9px 8px;
    white-space:nowrap;
    overflow:hidden;
    font-size:clamp(.68rem, .9vw, .84rem);
  }
  .tabs > .tab:not(.hide) i{
    flex:0 0 auto;
  }
  .tabs > .tab:not(.hide) .tab-label{
    min-width:0;
    overflow:hidden;
    text-overflow:ellipsis;
  }
  .tab{
    padding:8px 14px;
  }
}
.tab .tab-label{display:inline-block;vertical-align:middle}
.panel:not(.active){
  content-visibility:hidden;
  contain-intrinsic-size:auto 720px;
}
.panel.active{
  content-visibility:visible;
}
.tab{
  border:none;background:transparent;color:var(--muted);padding:8px 11px;border-radius:10px;cursor:pointer;font-weight:650;
  font-size:.86rem;line-height:1.15;transition:background .18s ease,color .18s ease,transform .18s ease,box-shadow .18s ease;
  will-change:transform;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
}
.tabs > .tab i{
  flex:0 0 auto;
  line-height:1;
}
.tabs > .tab .tab-label{
  line-height:1.15;
}
@media (max-width: 820px){
  .tabs{
    gap:5px;
    padding:5px 6px;
  }
  .tabs > .tab:not(.hide){
    display:inline-flex;
    align-items:center;
    justify-content:center;
    gap:6px;
    padding:8px 10px;
    font-size:.76rem;
    line-height:1.2;
  }
  .tabs > .tab:not(.hide) i{
    font-size:.78rem;
    width:1em;
    text-align:center;
  }
  .tabs > .tab:not(.hide) .tab-label{
    letter-spacing:.01em;
  }
}
.tab:hover:not(:disabled):not(.guest-disabled){
  color:var(--text);
  background:rgba(36,87,214,.06);
}
.tab.active{background:var(--primary);color:#fff;box-shadow:0 6px 16px rgba(36,87,214,.22)}
.tab.active:hover:not(:disabled){color:#fff;background:var(--primary)}
.tab:disabled,
.tab.guest-disabled{
  opacity:.45;
  cursor:not-allowed;
  background:#f8fafc;
  color:var(--muted);
}
.tab-menu-wrap{display:inline-flex}
.tabs .menu-dropdown{min-width:250px}

.loan-mode-switch{
  display:flex;
  gap:6px;
  flex-wrap:wrap;
  padding:4px;
  border:1px solid var(--line);
  border-radius:12px;
  background:var(--panel-2);
  width:fit-content;
  max-width:100%;
}
.loan-mode-btn{
  appearance:none;
  border:1px solid transparent;
  background:transparent;
