/* Triplem VIP shared destructive confirmation dialog */
.app-confirm-modal{
  position:fixed;
  inset:0;
  z-index:2147483646;
  display:grid;
  place-items:center;
  padding:clamp(14px,3vw,28px);
}
.app-confirm-modal.hide{display:none !important;}
.app-confirm-backdrop{
  position:absolute;
  inset:0;
  background:color-mix(in srgb,var(--overlay-backdrop,rgba(15,23,42,.62)) 90%,transparent);
  backdrop-filter:blur(12px) saturate(1.06);
  -webkit-backdrop-filter:blur(12px) saturate(1.06);
}
.app-confirm-dialog{
  position:relative;
  isolation:isolate;
  width:min(292px,calc(100vw - 36px));
  max-height:min(86dvh,620px);
  overflow:auto;
  scrollbar-width:none;
  color:var(--text);
  border:1px solid color-mix(in srgb,var(--danger) 18%,var(--glass-border,var(--line)));
  border-radius:19px;
  background:
    radial-gradient(120% 100% at 0 0,color-mix(in srgb,var(--danger) 8%,transparent),transparent 58%),
    linear-gradient(155deg,var(--surface-glass-strong,#fff),var(--surface-glass,var(--panel)));
  box-shadow:0 28px 80px rgba(15,23,42,.24),inset 0 1px 0 var(--glass-highlight,rgba(255,255,255,.58));
  backdrop-filter:blur(24px) saturate(1.22);
  -webkit-backdrop-filter:blur(24px) saturate(1.22);
  animation:appConfirmEnter .22s cubic-bezier(.22,1,.36,1) both;
}
.app-confirm-dialog::-webkit-scrollbar{display:none;}
.app-confirm-glint{
  position:absolute;
  z-index:-1;
  inset:0;
  overflow:hidden;
  border-radius:inherit;
  pointer-events:none;
}
.app-confirm-glint::after{
  content:"";
  position:absolute;
  top:-45%;
  left:108%;
  width:34%;
  height:190%;
  transform:rotate(16deg);
  background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--glass-highlight,#fff) 70%,transparent),transparent);
  opacity:.38;
  animation:appConfirmGlint 7.8s ease-in-out infinite;
}
.app-confirm-head{
  display:flex;
  align-items:center;
  gap:9px;
  padding:11px 12px 9px;
  border-bottom:1px solid var(--line);
}
.app-confirm-icon{
  width:32px;
  height:32px;
  flex:0 0 32px;
  display:grid;
  place-items:center;
  border-radius:11px;
  color:var(--danger);
  background:color-mix(in srgb,var(--danger) 11%,var(--surface-glass-strong,#fff));
  border:1px solid color-mix(in srgb,var(--danger) 22%,var(--line));
  box-shadow:inset 0 1px 0 var(--glass-highlight,rgba(255,255,255,.5));
}
.app-confirm-copy{min-width:0;}
.app-confirm-kicker{
  margin:0 0 2px;
  color:var(--danger);
  font-size:.68rem;
  font-weight:850;
  text-transform:uppercase;
  letter-spacing:.07em;
}
.app-confirm-copy h3{margin:0;color:var(--text);font-size:.96rem;line-height:1.25;letter-spacing:-.015em;}
.app-confirm-body{padding:10px 12px 11px;}
.app-confirm-message{margin:0;color:var(--text);font-size:.79rem;line-height:1.45;font-weight:650;}
.app-confirm-note{
  display:flex;
  align-items:flex-start;
  gap:8px;
  margin-top:8px;
  padding:7px 8px;
  border-radius:10px;
  border:1px solid var(--line);
  background:var(--surface-soft,var(--panel-2));
  color:var(--muted);
  font-size:.67rem;
  line-height:1.45;
}
