.app-confirm-actions{display:flex;justify-content:flex-end;gap:7px;margin-top:9px;padding:0;border:0;background:transparent;}
.app-confirm-actions .app-confirm-action-btn{width:30px;min-width:30px;height:30px;min-height:30px;padding:0;border-radius:10px;display:grid;place-items:center;line-height:1;}
.app-confirm-action-symbol{font-size:1rem;font-weight:900;line-height:1;transform:translateY(-.5px)}
.app-confirm-modal:not(.is-primary) .app-confirm-action-label{display:none;}
.app-confirm-modal.is-primary .app-confirm-action-btn{width:auto;min-width:76px;padding:0 10px;grid-auto-flow:column;gap:6px;}
.app-confirm-modal.is-primary .app-confirm-action-symbol{font-size:.98rem;}
.app-confirm-modal.is-primary .app-confirm-action-label{font-size:.68rem;font-weight:800;}
.app-confirm-actions .btn.danger{
  color:#fff !important;
  border-color:transparent !important;
  background:linear-gradient(135deg,color-mix(in srgb,var(--danger) 88%,#ff645a),var(--danger)) !important;
  box-shadow:0 10px 22px color-mix(in srgb,var(--danger) 20%,transparent) !important;
}
.app-confirm-modal.is-primary .app-confirm-dialog{border-color:color-mix(in srgb,var(--primary) 24%,var(--line));}
.app-confirm-modal.is-primary .app-confirm-icon,.app-confirm-modal.is-primary .app-confirm-kicker{color:var(--primary);}
.app-confirm-modal.is-primary .app-confirm-icon{background:color-mix(in srgb,var(--primary) 11%,var(--surface-glass-strong,#fff));border-color:color-mix(in srgb,var(--primary) 22%,var(--line));}
@keyframes appConfirmEnter{from{opacity:0;transform:translateY(10px) scale(.975)}to{opacity:1;transform:none}}
@keyframes appConfirmGlint{0%,64%,100%{left:108%}76%{left:-42%}}
@media(max-width:520px){
  .app-confirm-modal{padding:14px max(14px,env(safe-area-inset-left)) max(14px,env(safe-area-inset-bottom)) max(14px,env(safe-area-inset-right));}
  .app-confirm-dialog{width:min(100%,278px);border-radius:16px;}
