.tax-preview,
.inventory-sale-tax-summary{
  display:block;
  color:var(--muted);
  font-size:.66rem;
  line-height:1.25;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  min-width:0;
}
.tax-inline-grid{
  display:grid;
  grid-template-columns:minmax(130px,.8fr) minmax(110px,.7fr) minmax(170px,1fr) minmax(0,1.5fr);
  gap:10px;
  align-items:end;
}
.tax-inline-grid label{
  display:flex;
  flex-direction:column;
  gap:6px;
}
.tax-inline-grid .checkbox-line{
  flex-direction:row;
  align-items:center;
}
.vat-settings-body{
  display:grid;
  gap:10px;
}
.vat-settings-row{
  display:grid;
  grid-template-columns:72px minmax(100px,1fr) minmax(150px,1.2fr);
  gap:10px;
  align-items:center;
}
.vat-settings-currency{
  font-weight:700;
  color:var(--text);
}
.inventory-outstanding-banner{
  border:1px solid #d9e2f1;
  border-radius:12px;
  background:#fff;
  overflow:hidden;
  margin-bottom:12px;
}
.inventory-outstanding-panel{
  margin-bottom:0;
}
.inventory-outstanding-panel > summary{
  cursor:default;
}
.inventory-subview{
  display:block;
}
.inventory-stock-toolbar{
  display:flex;
  align-items:center;
  justify-content:flex-start;
  gap:8px;
  flex-wrap:wrap;
  margin-bottom:8px;
  padding-top:2px;
}
.inventory-customers-view{
  display:flex;
  flex-direction:column;
  gap:10px;
  padding-top:4px;
}
.inventory-customers-toolbar{
  display:flex;
  flex-direction:column;
  align-items:stretch;
  gap:8px;
}
.inventory-customers-toolbar-nav{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  flex-wrap:wrap;
}
.inventory-customers-toolbar-title{
  min-width:0;
}
.inventory-customers-toolbar-title strong{
  display:block;
  font-size:.95rem;
  font-weight:780;
  color:var(--text);
  line-height:1.25;
}
.inventory-customers-toolbar-title span{
  display:block;
  margin-top:2px;
  color:var(--muted);
  font-size:.78rem;
  line-height:1.35;
}
.inventory-outstanding-list-root{
  min-height:0;
}
.inventory-outstanding-empty-state{
  margin:0;
  padding:12px 2px 4px;
  color:var(--muted);
  font-size:.85rem;
  line-height:1.4;
}
.inventory-outstanding-banner > summary{
  cursor:pointer;
  list-style:none;
}
.inventory-outstanding-banner > summary::-webkit-details-marker{
  display:none;
}
.inventory-outstanding-banner:not([open]) > .inventory-outstanding-top{
  border-bottom:none;
}
.inventory-outstanding-banner.is-clear{
  border-color:var(--line);
}
.inventory-outstanding-top{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:10px 14px;
  background:#f8fafc;
  border-bottom:1px solid var(--line);
}
.inventory-outstanding-banner.is-clear .inventory-outstanding-top{
  border-bottom:none;
}
.inventory-outstanding-top p{
  margin:0;
  color:var(--muted);
  font-size:.82rem;
  line-height:1.35;
}
.inventory-outstanding-total{
  flex:0 0 auto;
  text-align:right;
  min-width:150px;
}
.inventory-outstanding-top-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  flex:0 0 auto;
}
.inventory-outstanding-top-actions > strong{
  color:var(--text);
  font-size:.9rem;
  line-height:1.25;
  white-space:nowrap;
}
.inventory-outstanding-total small,
.inventory-outstanding-money small{
  display:block;
  color:var(--muted);
  font-size:.68rem;
  font-weight:700;
  text-transform:uppercase;
}
.inventory-outstanding-total strong,
.inventory-outstanding-money strong{
  display:block;
  color:var(--text);
  font-size:.9rem;
  line-height:1.25;
  white-space:nowrap;
}
.inventory-outstanding-body{
  height:320px;
  display:flex;
  flex-direction:column;
  min-height:0;
}
.inventory-outstanding-panel .inventory-outstanding-body{
  height:min(62vh, 560px);
}
.inventory-outstanding-search{
  display:flex;
  align-items:center;
  gap:8px;
  padding:10px 14px;
  border-bottom:1px solid var(--line);
  background:#fff;
}
.inventory-outstanding-search-box{
  flex:1;
  min-width:0;
  position:relative;
}
.inventory-outstanding-search-box i{
  position:absolute;
  left:11px;
  top:50%;
  transform:translateY(-50%);
  color:var(--muted);
  font-size:.82rem;
}
.inventory-outstanding-search-box .input{
  width:100%;
  padding-left:34px;
}
.inventory-outstanding-members{
  flex:1;
  min-height:0;
  overflow:auto;
}
.inventory-outstanding-member{
  border-top:1px solid var(--line);
}
.inventory-outstanding-member.search-only{
  background:#fbfdff;
}
.inventory-outstanding-member:first-child{
  border-top:none;
}
.inventory-outstanding-member summary{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:10px 14px;
  cursor:pointer;
  list-style:none;
}
.inventory-outstanding-member summary::-webkit-details-marker{
  display:none;
}
.inventory-outstanding-member summary span{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-weight:760;
}
.inventory-outstanding-name{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  border:0;
  background:transparent;
  color:var(--primary);
  padding:0;
  font:inherit;
  font-weight:780;
  text-align:left;
  cursor:pointer;
}
.inventory-outstanding-name:hover{
  text-decoration:underline;
}
.inventory-outstanding-member summary strong{
  flex:0 0 auto;
  color:var(--muted);
  font-size:.78rem;
  font-weight:760;
  text-align:right;
}
.inventory-outstanding-list{
  border-top:1px solid var(--line);
}
.inventory-outstanding-row{
  display:grid;
  grid-template-columns:minmax(0,2.1fr) minmax(105px,.8fr) minmax(105px,.8fr) minmax(115px,.9fr) auto;
  gap:10px;
  align-items:center;
  padding:10px 14px;
  border-top:1px solid var(--line);
}
.inventory-outstanding-row:first-child{
  border-top:none;
}
.inventory-outstanding-main{
  min-width:0;
}
.inventory-outstanding-main strong{
  display:block;
  color:var(--text);
  font-size:.88rem;
  line-height:1.25;
}
.inventory-outstanding-main span{
  display:block;
  margin-top:2px;
  color:var(--muted);
  font-size:.76rem;
  line-height:1.25;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.inventory-outstanding-money{
  min-width:0;
}
.inventory-outstanding-money.is-due strong{
  color:var(--danger);
}
.inventory-outstanding-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:6px;
  flex-wrap:nowrap;
}
.inventory-outstanding-empty{
  padding:18px 14px;
  color:var(--muted);
  font-size:.86rem;
}
.note-content-preview{
  font-size:.9rem;
  color:var(--text);
  line-height:1.5;
  white-space:pre-wrap;
  word-wrap:break-word;
  overflow-wrap:break-word;
  word-break:break-word;
  max-width:100%;
  width:100%;
}
.note-content-preview.is-collapsed{
  max-height:3em;
  overflow:hidden;
}
.note-see-more-btn{
  appearance:none;
  border:0;
  background:transparent;
  color:var(--primary);
  padding:4px 0 0;
  font:inherit;
  font-size:.78rem;
  font-weight:800;
  cursor:pointer;
}
.note-see-more-btn:hover{
  text-decoration:underline;
}
.settlement-invoice-list{
  display:grid;
  gap:8px;
  max-height:190px;
  overflow:auto;
  padding:2px;
}
.settlement-invoice-option{
  display:flex;
  align-items:flex-start;
  gap:9px;
  padding:9px 10px;
  border:1px solid var(--line);
  border-radius:10px;
  background:#fff;
}
.settlement-invoice-option input{
  margin-top:2px;
  flex:0 0 auto;
}
.settlement-invoice-option span{
  min-width:0;
}
.settlement-invoice-option strong,
.settlement-invoice-option small{
  display:block;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.settlement-invoice-option strong{
  color:var(--text);
  font-size:.86rem;
  line-height:1.2;
}
.settlement-invoice-option small{
  margin-top:2px;
  color:var(--muted);
  font-size:.75rem;
  line-height:1.25;
}
.inventory-customer-dialog{
  width:min(1080px, calc(100vw - 28px));
  max-width:100%;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  min-width:0;
}
.inventory-customer-dialog .modal-head{
  flex:0 0 auto;
  min-width:0;
}
.inventory-customer-dialog .modal-body{
  flex:1 1 auto;
  min-width:0;
  overflow-x:hidden;
  overflow-y:auto;
  max-height:calc(100vh - 108px);
}
.inventory-customer-head-actions{
  display:flex;
  align-items:center;
  gap:8px;
  flex:0 0 auto;
}
.inventory-customer-record{
  display:grid;
  gap:14px;
  min-width:0;
  max-width:100%;
}
.inventory-customer-summary{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:8px;
  min-width:0;
}
.inventory-customer-summary > div{
  border:1px solid var(--line);
  border-radius:10px;
  background:#f8fafc;
  padding:10px;
  min-width:0;
}
.inventory-customer-summary small{
  display:block;
  color:var(--muted);
  font-size:.68rem;
  font-weight:800;
  text-transform:uppercase;
}
.inventory-customer-summary strong{
  display:block;
  margin-top:4px;
  color:var(--text);
  font-size:.9rem;
  line-height:1.25;
  overflow-wrap:anywhere;
  word-break:break-word;
  white-space:normal;
}
.inventory-customer-contact{
  display:flex;
  flex-wrap:wrap;
  gap:8px 14px;
  color:var(--muted);
  font-size:.84rem;
  min-width:0;
}
.inventory-customer-section{
  min-width:0;
  max-width:100%;
}
.inventory-customer-section h4{
  margin:0 0 8px;
  color:var(--text);
  font-size:.95rem;
}
.inventory-customer-section .table-wrap{
  max-height:min(320px, 42vh);
  max-width:100%;
  width:100%;
  overflow:auto;
  overscroll-behavior:contain;
}
.inventory-customer-section table{
  width:100%;
  min-width:0;
  table-layout:fixed;
}
.inventory-customer-section thead th,
.inventory-customer-section tbody td{
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  vertical-align:middle;
  line-height:1.25;
  padding:6px 7px;
  font-size:.74rem;
}
.inventory-customer-section thead th{
  white-space:nowrap;
}
.inventory-customer-section td .tiny{
  white-space:nowrap;
}
.inventory-stmt-details{
  white-space:normal !important;
  display:-webkit-box;
  -webkit-box-orient:vertical;
  -webkit-line-clamp:2;
  line-clamp:2;
  overflow:hidden;
  text-overflow:ellipsis;
  overflow-wrap:anywhere;
  word-break:break-word;
  max-width:100%;
  font-size:.7rem;
  color:var(--muted);
  line-height:1.3;
  vertical-align:top;
}
@media (max-width: 768px){
  .inventory-outstanding-top,
  .inventory-outstanding-member summary{
    align-items:flex-start;
    flex-direction:column;
  }
  .inventory-outstanding-body{
    height:min(58vh, 420px);
  }
  .inventory-stock-toolbar,
  .inventory-customers-toolbar-nav{
    justify-content:flex-start;
    flex-wrap:wrap;
    gap:6px;
  }
  .inventory-stock-toolbar > .tiny,
  .inventory-customers-toolbar-nav > .tiny{
    flex:0 1 auto;
    white-space:nowrap;
  }
  .inventory-grid-sort{
    margin-left:auto;
    flex:1 1 auto;
    justify-content:flex-end;
    min-width:min(100%, 200px);
  }
  .inventory-customers-toolbar{
    gap:6px;
  }
  .inventory-customers-toolbar-title strong{
    font-size:.9rem;
  }
  .inventory-customers-toolbar-title span{
    font-size:.74rem;
  }
  .inventory-outstanding-search{
    align-items:stretch;
    flex-wrap:wrap;
  }
  .inventory-outstanding-search-box{
    flex:1 1 100%;
  }
  .inventory-outstanding-total,
  .inventory-outstanding-top-actions,
  .inventory-outstanding-member summary strong{
    width:100%;
    text-align:left;
  }
  .inventory-outstanding-top-actions{
    justify-content:flex-start;
    flex-wrap:wrap;
  }
  .inventory-outstanding-row{
    grid-template-columns:1fr 1fr;
  }
  .inventory-outstanding-main,
  .inventory-outstanding-actions{
    grid-column:1 / -1;
  }
  .inventory-outstanding-actions{
    justify-content:flex-start;
    flex-wrap:wrap;
  }
  .inventory-customer-head-actions{
    align-self:stretch;
    justify-content:space-between;
  }
  .inventory-customer-summary{
    grid-template-columns:1fr 1fr;
  }
}

.expense-section-anchor{margin-top:16px;margin-bottom:2px;}
.expense-section-anchor:first-child{margin-top:0;}
.expense-section-title{margin:0 0 8px;font-size:1rem;font-weight:760;color:var(--text);}
.expense-section-toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:10px;}
.expense-toolbar-hint{font-size:.8rem;color:var(--muted);flex:1;min-width:200px;line-height:1.45;}
.expense-by-currency{margin-top:4px;}

/* -- Product barcodes + camera scanner (additive) ------------------------- */
.inventory-barcodes-view .inventory-customers-toolbar-title span{
  font-size:.68rem;
}
.inventory-barcodes-list-root{
  display:grid;
  gap:8px;
}
.inv-barcode-toolbar{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  align-items:end;
  justify-content:space-between;
  margin-bottom:6px;
}
.inv-barcode-search{
  display:grid;
  gap:2px;
  min-width:min(100%, 220px);
  flex:1 1 180px;
  font-size:.66rem;
  color:var(--muted);
  font-weight:550;
}
.inv-barcode-search .input{
  min-height:28px;
  height:28px;
  font-size:.72rem;
  padding:2px 8px;
  border-radius:7px;
}
.inv-barcode-filter{
  display:grid;
  gap:2px;
  min-width:120px;
  font-size:.66rem;
  color:var(--muted);
  font-weight:550;
}
.inv-barcode-filter .select,
.inv-barcode-filter .input{
  min-height:28px;
  height:28px;
  font-size:.72rem;
  padding:2px 8px;
  border-radius:7px;
  width:100%;
  box-sizing:border-box;
}
.inv-barcode-filter .input{
  min-width:72px;
  max-width:96px;
}
.inv-barcode-actions{
  display:flex;
  flex-wrap:wrap;
  gap:4px;
  align-items:center;
}
.inv-barcode-sync-banner{
  font-size:.68rem;
  color:#92400e;
  background:rgba(251,191,36,.16);
  border:1px solid rgba(245,158,11,.35);
  border-radius:8px;
  padding:6px 8px;
  margin-bottom:4px;
}
.inv-barcode-list{
  display:grid;
  gap:4px;
}
.inv-barcode-qty-hint{
  font-size:.64rem;
  color:var(--muted);
  margin:-2px 0 6px;
}
.inv-barcode-qty-input{
  width:64px;
  min-width:56px;
  min-height:26px;
  height:26px;
  padding:2px 6px;
  font-size:.68rem;
  border-radius:7px;
  text-align:center;
}
.inv-barcode-row{
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto auto auto;
  gap:8px;
  align-items:center;
  border:1px solid var(--line);
  border-radius:8px;
  padding:6px 8px;
  background:var(--card,#fff);
  cursor:pointer;
}
.inv-barcode-main{
  min-width:0;
  display:grid;
  gap:1px;
}
.inv-barcode-main strong{
  font-size:.74rem;
  font-weight:650;
  line-height:1.2;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.inv-barcode-main span{
  font-size:.62rem;
  color:var(--muted);
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.inv-barcode-meta{
  text-align:right;
  display:grid;
  gap:1px;
}
.inv-barcode-meta em{
  font-style:normal;
  font-size:.58rem;
  font-weight:700;
}
.inv-barcode-meta em.is-ok{ color:#047857; }
.inv-barcode-meta em.is-out{ color:#b91c1c; }
.inv-barcode-meta strong{
  font-size:.7rem;
  white-space:nowrap;
}

.inv-scanner-overlay{
  position:fixed;
  inset:0;
  z-index:1155;
  background:rgba(15,23,42,.38);
  display:flex;
  align-items:center;
  justify-content:center;
  padding:max(10px, env(safe-area-inset-top)) 10px max(10px, env(safe-area-inset-bottom));
}
.inv-scanner-overlay.hide{ display:none; }
.inv-scanner-shell{
  width:min(560px, 100%);
  max-height:min(86dvh, 640px);
  background:var(--card, #fff);
  color:var(--text);
  border:1px solid var(--line);
  border-radius:14px;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  box-shadow:0 18px 40px rgba(16,24,40,.16);
}
.inv-scanner-head{
  display:flex;
  justify-content:space-between;
  gap:8px;
  align-items:flex-start;
  padding:8px 10px;
  border-bottom:1px solid var(--line);
  background:var(--panel-2, var(--card, #fff));
}
.inv-scanner-head h3{
  margin:0;
  font-size:.82rem;
  font-weight:700;
  color:var(--text);
}
.inv-scanner-head p{
  margin:2px 0 0;
  font-size:.64rem;
  color:var(--muted);
  line-height:1.3;
  max-width:42ch;
}
.inv-scanner-online{
  display:inline-block;
  margin-top:4px;
  font-size:.56rem;
  font-weight:700;
  letter-spacing:.02em;
  color:#047857;
  background:rgba(16,185,129,.12);
  border:1px solid rgba(16,185,129,.28);
  border-radius:999px;
  padding:1px 6px;
}
.inv-scanner-online.is-offline{
  color:#b45309;
  background:rgba(245,158,11,.12);
  border-color:rgba(245,158,11,.35);
}
.inv-scanner-body{
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(180px,.95fr);
  gap:0;
  min-height:0;
  flex:1 1 auto;
}
.inv-scanner-camera{
  position:relative;
  min-height:0;
  background:#0f172a;
  display:flex;
  flex-direction:column;
  border-right:1px solid var(--line);
}
.inv-scanner-camera video{
  width:100%;
  flex:0 0 auto;
  object-fit:cover;
  height:200px;
  max-height:32vh;
  background:#0f172a;
}
.inv-scanner-frame{
  pointer-events:none;
  position:absolute;
  left:50%;
  top:50%;
  width:min(92%, 320px);
  height:min(58%, 110px);
  max-height:120px;
  transform:translate(-50%,-58%);
  border:1.5px dashed rgba(255,255,255,.35);
  border-radius:10px;
  box-shadow:none;
  transition:border-color .15s ease, background-color .15s ease;
}
.inv-scanner-frame.is-ok{
  border-color:#059669;
  border-style:solid;
  background:rgba(5,150,105,.12);
  box-shadow:none;
}
.inv-scanner-frame.is-miss{
  border-color:#dc2626;
  border-style:solid;
  background:rgba(220,38,38,.1);
  box-shadow:none;
}
.inv-scanner-manual{
  display:grid;
  gap:3px;
  padding:6px 8px 8px;
  background:var(--panel-2, var(--card, #fff));
  border-top:1px solid var(--line);
  font-size:.6rem;
  color:var(--muted);
  position:relative;
  z-index:2;
}
.inv-scanner-lookup-label{
  font-size:.6rem;
  color:var(--muted);
  font-weight:550;
}
.inv-scanner-lookup{
  display:flex;
  gap:5px;
  align-items:center;
}
.inv-scanner-lookup .input{
  flex:1 1 auto;
  min-height:28px;
  height:28px;
  border-radius:7px;
  font-size:.72rem;
  padding:2px 8px;
}
.inv-scanner-lookup .tiny{
  min-height:28px;
  flex:0 0 auto;
}
.inv-scanner-lookup-results{
  position:absolute;
  left:8px;
  right:8px;
  bottom:calc(100% - 1px);
