}
.inv-scanner-progress{
  display:flex;
  flex-direction:column;
  min-height:0;
  background:var(--card, #fff);
}
.inv-scanner-progress-head{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:6px;
  padding:6px 8px;
  border-bottom:1px solid var(--line);
  font-size:.68rem;
  color:var(--text);
}
.inv-scanner-progress-list{
  flex:1 1 auto;
  overflow:auto;
  padding:5px;
