  gap:3px;
  align-content:start;
  min-height:72px;
  max-height:none;
}
.inv-scan-empty{
  color:var(--muted);
  font-size:.66rem;
  padding:10px 6px;
  text-align:center;
}
.inv-scan-row{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto auto auto;
  gap:4px;
  align-items:center;
  padding:5px 6px;
  border-radius:8px;
  background:var(--panel-2, rgba(15,23,42,.03));
  border:1px solid var(--line);
}
.inv-scan-main{
  min-width:0;
  display:grid;
  gap:0;
}
.inv-scan-main strong{
  font-size:.66rem;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  color:var(--text);
}
.inv-scan-main span{
  font-size:.56rem;
  color:var(--muted);
}
.inv-scan-qty{
  display:inline-flex;
  align-items:center;
  gap:2px;
}
.inv-scan-qty em{
  font-style:normal;
  min-width:1.2em;
  text-align:center;
  font-size:.68rem;
  font-weight:700;
  color:var(--text);
}
.inv-scan-qty .tiny,
.inv-scan-rm{
  min-height:22px;
  min-width:22px;
  padding:0 5px;
  color:var(--text);
}
.inv-scan-total{
  font-size:.64rem;
  white-space:nowrap;
  color:var(--text);
}
.inv-scanner-progress-actions{
  display:flex;
  gap:3px;
  align-items:center;
  flex-wrap:wrap;
  justify-content:flex-end;
}
.inv-scanner-thermal-size select{
  min-height:22px;
  border-radius:6px;
  border:1px solid var(--line);
  background:var(--card, #fff);
  color:var(--text);
  font-size:.6rem;
  padding:0 3px;
}
.inv-scanner-progress-totals{
  display:flex;
  justify-content:space-between;
  gap:8px;
  align-items:center;
  padding:6px 8px;
  border-top:1px solid var(--line);
  font-size:.68rem;
  background:var(--panel-2, var(--card, #fff));
  color:var(--text);
}
.inv-scan-stats{
  display:flex;
  gap:7px;
  color:var(--muted);
  font-size:.58rem;
}
.inventory-scanner-host,
.inv-scanner-section-card{
  margin-top:4px;
}
.inv-scanner-section-card{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
  justify-content:space-between;
  align-items:center;
  border:1px solid var(--line);
  border-radius:10px;
  padding:10px 12px;
  background:var(--card,#fff);
}
.inv-scanner-section-card strong{
  display:block;
  font-size:.82rem;
  margin-bottom:2px;
}
.inv-scanner-section-card p{
  margin:0;
  font-size:.68rem;
  color:var(--muted);
  max-width:42ch;
  line-height:1.4;
}
.inv-scanner-section-actions{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
}
.sales-invoice-thermal-wrap{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
  align-items:end;
  width:100%;
}
.sales-invoice-thermal-size{
  display:grid;
  gap:2px;
  font-size:.62rem;
  color:var(--muted);
  font-weight:550;
}
.sales-invoice-thermal-size select{
  min-height:34px;
  border-radius:8px;
  border:1px solid var(--line);
  padding:0 8px;
  font-size:.72rem;
  background:var(--card,#fff);
  color:var(--text);
}
.sales-invoice-success-actions #salesInvoiceSuccessThermalBtn{
  min-height:34px;
  flex:1 1 auto;
}

@media (max-width: 720px){
  .inv-scanner-overlay{
    align-items:flex-end;
    padding:8px 8px max(8px, env(safe-area-inset-bottom));
  }
  .inv-scanner-shell{
    width:100%;
    max-height:min(88dvh, 620px);
    border-radius:14px 14px 10px 10px;
  }
  .inv-scanner-body{
    grid-template-columns:1fr;
    grid-template-rows:auto minmax(0,1fr);
  }
  .inv-scanner-camera{
    border-right:0;
    border-bottom:1px solid var(--line);
  }
  .inv-scanner-camera video{
    height:170px;
    max-height:28vh;
  }
  .inv-scanner-frame{
    height:min(62%, 96px);
  }
  .inv-scanner-progress{
    max-height:none;
    min-height:0;
  }
  .inv-scanner-progress-list{
    max-height:28vh;
  }
  .inv-scan-row{
    grid-template-columns:minmax(0,1fr) auto auto;
    grid-template-areas:
      "main qty rm"
      "main total rm";
  }
  .inv-scan-main{ grid-area:main; }
  .inv-scan-qty{ grid-area:qty; }
  .inv-scan-total{ grid-area:total; }
  .inv-scan-rm{ grid-area:rm; }
}
@media (max-width: 860px){
  .inv-barcode-row{
    grid-template-columns:auto minmax(0,1fr) auto auto;
    grid-template-areas:
      "check main print qty"
      "check meta print qty";
    gap:4px 8px;
  }
  .inv-barcode-row input[type="checkbox"]{ grid-area:check; }
  .inv-barcode-main{ grid-area:main; }
  .inv-barcode-meta{
    grid-area:meta;
    text-align:left;
    display:flex;
    gap:8px;
    align-items:center;
  }
  .inv-barcode-qty-input{ grid-area:qty; }
  .inv-barcode-row .tiny{ grid-area:print; }
}


/* Pending local inventory rows keep their database Save action attached to the item. */
