.lock{
  position:fixed;inset:0;background:linear-gradient(135deg, rgba(246,247,249,0.6) 0%, rgba(236,240,249,0.5) 100%);backdrop-filter:blur(8px);display:grid;place-items:center;z-index:100;padding:16px;
}
.lock-card{
  width:min(480px,100%);background:#fff;border:1px solid var(--line);border-radius:24px;box-shadow:0 20px 40px rgba(16,24,40,.12), 0 8px 16px rgba(16,24,40,.08);padding:32px;position:relative;overflow:hidden;}
.lock-card::before{
  content:'';position:absolute;top:0;left:0;right:0;height:4px;background:linear-gradient(90deg, var(--primary) 0%, #4a7fff 50%, var(--primary) 100%);
  background-size:200% 100%;animation:shimmer 3s ease-in-out infinite;
}
@keyframes shimmer{
  0%,100%{background-position:200% 0;}
  50%{background-position:-200% 0;}
}
.lock-card h2{margin:0 0 12px;font-size:1.32rem;font-weight:800;letter-spacing:-.02em;color:var(--text);}
.lock-card p{margin:0 0 24px;color:var(--muted);font-size:.94rem;line-height:1.6;}
.lock-row{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center}
.lock-grid{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center}
.lock-grid .lock-input-full{grid-column:1/-1}
.lock-error{min-height:1.1em;margin-top:12px;color:var(--danger);font-size:.88rem;font-weight:500;padding:8px 12px;background:rgba(180,35,24,.06);border-radius:8px;border:1px solid rgba(180,35,24,.15);display:none;}
.lock-error.show{display:block;animation:errorSlide 0.3s ease-out;}
@keyframes errorSlide{
  from{opacity:0;transform:translateY(-8px);}
  to{opacity:1;transform:translateY(0);}
}
.hide{display:none !important}


/* ===== 08-landing-auth.css ===== */
/* Split from styles.css lines 5813-9923 — welcome, login, landing, trial promo. Do not reorder relative to other 0N-*.css files. */
/* Welcome Screen Styles */
.welcome-screen{
  position:fixed;inset:0;background:linear-gradient(135deg, rgba(246,247,249,0.6) 0%, rgba(236,240,249,0.5) 100%);backdrop-filter:blur(8px);display:grid;place-items:center;z-index:95;padding:16px;
  animation:welcomeBgFadeIn 0.4s ease-out;
}

@keyframes welcomeBgFadeIn{
  from{opacity:0;transform:scale(1.05);}
  to{opacity:1;transform:scale(1);}
}

.welcome-content{
  text-align:center;color:var(--text);
  animation:welcomeContentSlideUp 0.5s ease-out 0.2s both;
}

@keyframes welcomeContentSlideUp{
  from{opacity:0;transform:translateY(20px);}
  to{opacity:1;transform:translateY(0);}
}

.welcome-logo{
  margin-bottom:20px;
  animation:welcomeLogoFadeIn 0.4s ease-out both;
}

.welcome-logo img{
  width:120px;
  height:120px;
  object-fit:contain;
}

@keyframes welcomeLogoFadeIn{
  from{opacity:0;transform:scale(0.8);}
  to{opacity:1;transform:scale(1);}
}

.welcome-text{
  display:flex;flex-direction:column;align-items:center;gap:12px;
}

.welcome-title{
  margin:0;font-size:2.5rem;font-weight:800;letter-spacing:-0.02em;line-height:1.2;
  color:var(--text);
  animation:welcomeTitleFadeIn 0.5s ease-out 0.3s both;
}

@keyframes welcomeTitleFadeIn{
  from{opacity:0;transform:translateY(-10px);}
  to{opacity:1;transform:translateY(0);}
}

.welcome-name{
  margin:0;font-size:1.5rem;font-weight:600;letter-spacing:-0.01em;line-height:1.4;
  color:var(--muted);
  animation:welcomeNameFadeIn 0.5s ease-out 0.4s both;
}

@keyframes welcomeNameFadeIn{
  from{opacity:0;transform:scale(0.9);}
  to{opacity:1;transform:scale(1);}
}

/* Welcome screen exit animation */
.welcome-screen.exit-animation{
  animation:welcomeExit 0.6s ease-in-out forwards;
}

@keyframes welcomeExit{
  0%{opacity:1;transform:scale(1);}
  50%{opacity:1;transform:scale(1);}
  100%{opacity:0;transform:scale(0.95);pointer-events:none;}
}

.welcome-screen.exit-animation .welcome-content{
  animation:welcomeContentSlideOut 0.6s ease-in-out forwards;
}

@keyframes welcomeContentSlideOut{
  0%{opacity:1;transform:translateY(0) translateX(0);}
  100%{opacity:0;transform:translateY(-10px) translateX(50px);}
}

/* App entrance animation */
.app-enter-animation{
  animation:appSlideInFromRight 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

@keyframes appSlideInFromRight{
  from{opacity:0;transform:translateX(100%);}
  to{opacity:1;transform:translateX(0);}
}

/* Enhanced Login Form Styles */
.login-header{
  text-align:center;margin-bottom:32px;
}
.login-header h2,
.login-header h3{
  margin:0;font-size:1.8rem;font-weight:800;letter-spacing:-.03em;color:var(--text);
  background:linear-gradient(135deg, var(--text) 0%, var(--primary) 100%);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
}
.login-subtitle{
  margin:8px 0 0;color:var(--muted);font-size:.96rem;line-height:1.5;
}

.login-form{
  display:flex;flex-direction:column;gap:20px;margin-bottom:24px;
}
.form-group{
  display:flex;flex-direction:column;gap:6px;
}
.form-label{
  font-size:.84rem;font-weight:600;color:var(--text);letter-spacing:-.01em;
}
.input-wrapper{
  position:relative;display:flex;align-items:center;
}
.input-icon{
  position:absolute;right:16px;font-size:1.1rem;color:var(--muted);
  pointer-events:none;transition:color 0.2s ease;
}
.input-wrapper.has-pw-eye .input-icon{
  left:14px;
