/* Final M matches TRIPLE typography; blinks 3× every ~3s for a subtle “triple M” cue. */
.brand-m-triple{
  display:inline;
  margin:0;
  padding:0;
  letter-spacing:inherit;
  font-weight:inherit;
  font-size:inherit;
  line-height:inherit;
  color:inherit;
  text-shadow:none;
  animation:brand-m-triple-pulse 4.5s ease-in-out infinite;
  animation-delay:1.2s;
}
.brand-m-triple::before,
.brand-m-triple::after{
  content:none;
  display:none;
}
@keyframes brand-m-triple-pulse{
  /* Hold solid for ~3s */
  0%,
  66% { opacity:1; }
  /* Blink 1 */
  70% { opacity:0.12; }
  74% { opacity:1; }
  /* Blink 2 */
  78% { opacity:0.12; }
  82% { opacity:1; }
  /* Blink 3 */
  86% { opacity:0.12; }
  90%,
  100% { opacity:1; }
}
