/* Landing content overlay (section tabs/sheet) */
.landing-content-overlay{
  position:fixed;
  inset:0;
  z-index:850;
  display:grid;
  place-items:start center;
  align-content:start;
  padding:max(10px, env(safe-area-inset-top, 0px)) 0 0;
  pointer-events:none;
}
.landing-content-overlay.is-app-overlay{
  z-index:12050;
}
.landing-content-overlay.hide{
  display:none;
}
.landing-content-overlay.is-open{
  pointer-events:auto;
}
.landing-content-backdrop{
  position:absolute;
  inset:0;
  background:rgba(15,23,42,.42);
  backdrop-filter:blur(8px);
  opacity:0;
  transition:opacity .28s ease;
}
.landing-content-overlay.is-open .landing-content-backdrop{
  opacity:1;
  animation:landing-overlay-fade .28s ease both;
}
.landing-content-sheet{
  position:relative;
  z-index:1;
  width:min(760px, 100%);
  height:min(86vh, calc(100% - max(10px, env(safe-area-inset-top, 0px))));
  height:min(86dvh, calc(100% - max(10px, env(safe-area-inset-top, 0px))));
  max-height:min(86vh, calc(100% - max(10px, env(safe-area-inset-top, 0px))));
  max-height:min(86dvh, calc(100% - max(10px, env(safe-area-inset-top, 0px))));
  min-height:0;
  display:flex;
  flex-direction:column;
  border:1px solid rgba(255,255,255,.72);
  border-radius:0 0 22px 22px;
  background:
    linear-gradient(160deg, rgba(255,255,255,.96) 0%, rgba(246,249,255,.94) 100%);
  box-shadow:0 16px 48px rgba(16,24,40,.18);
  transform:translateY(-16px);
  opacity:0;
  transition:transform .32s cubic-bezier(.22,1,.36,1), opacity .28s ease;
  overflow:hidden;
}
.landing-content-overlay.is-open .landing-content-sheet{
  transform:translateY(0);
  opacity:1;
  animation:landing-sheet-in .34s cubic-bezier(.22,1,.36,1) both;
}
@keyframes landing-overlay-fade{
  from{opacity:0;}
  to{opacity:1;}
}
@keyframes landing-sheet-in{
  from{opacity:0;transform:translateY(-16px);}
  to{opacity:1;transform:translateY(0);}
}
.landing-content-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:12px 16px 8px;
  border-bottom:1px solid rgba(208,213,221,.45);
