/* Blinking offer ticker */
.landing-offer-ticker{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  flex-wrap:wrap;
  padding:8px 12px;
  border-radius:14px;
  border:1px solid rgba(220,38,38,.22);
  background:linear-gradient(135deg, rgba(254,242,242,.95), rgba(255,247,237,.92));
  box-shadow:0 10px 28px rgba(220,38,38,.08);
  text-align:center;
}
.landing-offer-ticker-pulse{
  color:#dc2626;
  font-size:.55rem;
  line-height:1;
  animation:landing-offer-blink 1.1s ease-in-out infinite;
}
.landing-offer-ticker-text{
  margin:0;
  color:#7f1d1d;
  font-size:.78rem;
  font-weight:650;
  line-height:1.35;
}
.landing-offer-ticker-text strong{
  font-weight:850;
  letter-spacing:.01em;
}
.landing-offer-ticker-sep{
  margin:0 4px;
  opacity:.55;
}
.landing-offer-ticker-cta{
  appearance:none;
  border:0;
  background:transparent;
  color:#b91c1c;
  font:inherit;
  font-size:.74rem;
  font-weight:800;
  cursor:pointer;
  padding:2px 4px;
  text-decoration:underline;
  text-underline-offset:2px;
  animation:landing-offer-blink 1.4s ease-in-out infinite;
}
.landing-offer-ticker-cta:hover{
  color:#991b1b;
}
@keyframes landing-offer-blink{
  0%, 100%{ opacity:1; }
  50%{ opacity:.35; }
}
.landing-trial-badge--blink{
  animation:landing-offer-blink 1.25s ease-in-out infinite;
}
.landing-cta-pulse{
  animation:landing-cta-glow 1.8s ease-in-out infinite;
}
@keyframes landing-cta-glow{
