/* Founder-parity optical glass tags + landing contact icons */
:is(.landing-eyebrow,.section-kicker,.login-kicker,.landing-trial-badge){
  position:relative;
  isolation:isolate;
  overflow:hidden;
  width:max-content;
  max-width:100%;
  padding:5px 10px;
  border:1px solid rgba(255,255,255,.72);
  border-radius:999px;
  background:linear-gradient(145deg,rgba(255,255,255,.68),rgba(255,255,255,.28));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.82),0 7px 20px rgba(36,87,214,.07);
  backdrop-filter:blur(12px) saturate(1.18);
  -webkit-backdrop-filter:blur(12px) saturate(1.18);
}
:is(.landing-eyebrow,.section-kicker,.login-kicker,.landing-trial-badge)::after,
.landing-offer-ticker::before,
.landing-content-tab::after,
.landing-info-action::after,
.signin-overlay-info::after{
  content:"";
  position:absolute;
  z-index:0;
  top:-55%;
  left:112%;
  width:34%;
  height:210%;
  pointer-events:none;
  transform:rotate(17deg);
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.78),rgba(255,255,255,.18),transparent);
  opacity:.48;
  animation:landingLensSweepRtl 8.6s cubic-bezier(.22,.65,.32,1) infinite;
}
:is(.landing-eyebrow,.section-kicker,.login-kicker,.landing-trial-badge) > *,
.landing-offer-ticker > *,
.landing-content-tab > *,
.landing-info-action > *,
.signin-overlay-info > *{position:relative;z-index:1;}
.landing-content-tab,.landing-info-action,.signin-overlay-info,.landing-offer-ticker{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  backdrop-filter:blur(13px) saturate(1.18);
  -webkit-backdrop-filter:blur(13px) saturate(1.18);
}
.landing-content-tab{
  border-color:rgba(255,255,255,.62);
  background:linear-gradient(145deg,rgba(255,255,255,.58),rgba(255,255,255,.24));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.72);
}
.landing-info-action{
  border-color:rgba(255,255,255,.68);
  background:linear-gradient(145deg,rgba(255,255,255,.62),rgba(255,255,255,.26));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.76),0 9px 24px rgba(16,24,40,.06);
}
.signin-overlay-info{
  border:1px solid rgba(255,255,255,.68);
  background:linear-gradient(145deg,rgba(255,255,255,.78),rgba(36,87,214,.12));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.85),0 7px 18px rgba(36,87,214,.13);
}
.landing-offer-ticker{
  border-color:rgba(255,255,255,.72);
  background:linear-gradient(135deg,rgba(254,242,242,.88),rgba(255,255,255,.60),rgba(255,247,237,.84));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.82),0 10px 26px rgba(220,38,38,.07);
}
@keyframes landingLensSweepRtl{0%,67%,100%{left:112%}79%{left:-42%}}

.landing-footer-contact-icons{
  display:flex;
  flex-wrap:wrap;
  justify-content:center;
  align-items:center;
  gap:8px;
}
.landing-footer-social-icon{
  width:36px;
  height:36px;
  display:inline-grid;
  place-items:center;
  flex:0 0 36px;
  border-radius:12px;
  color:#344054;
  text-decoration:none;
  border:1px solid rgba(255,255,255,.72);
  background:linear-gradient(145deg,rgba(255,255,255,.72),rgba(255,255,255,.34));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.82),0 7px 18px rgba(15,23,42,.06);
  backdrop-filter:blur(10px);
  -webkit-backdrop-filter:blur(10px);
  transition:transform .18s ease,color .18s ease,border-color .18s ease,box-shadow .18s ease;
}
.landing-footer-social-icon:hover,.landing-footer-social-icon:focus-visible{
  color:var(--primary);
  transform:translateY(-2px);
  border-color:rgba(36,87,214,.22);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.88),0 10px 22px rgba(36,87,214,.10);
  outline:none;
}
.landing-footer-social-icon--whatsapp:hover,.landing-footer-social-icon--whatsapp:focus-visible{color:#128c7e;}
.landing-whatsapp i,.fraud-alert-channels .fa-whatsapp,.landing-footer-social-icon .fa-whatsapp{font-family:"Font Awesome 6 Brands";font-weight:400;}

#lockScreen.landing-low-power :is(.landing-eyebrow,.section-kicker,.login-kicker,.landing-trial-badge,.landing-content-tab,.landing-info-action,.signin-overlay-info,.landing-offer-ticker)::after,
#lockScreen.landing-low-power .landing-offer-ticker::before{animation:none !important;opacity:0 !important;}
@media(prefers-reduced-motion:reduce){
  :is(.landing-eyebrow,.section-kicker,.login-kicker,.landing-trial-badge,.landing-content-tab,.landing-info-action,.signin-overlay-info)::after,
  .landing-offer-ticker::before{animation:none !important;opacity:0 !important;}
