/* ===== 09-shell-overview.css ===== */
/* Split from styles.css lines 9924-10551 — wallets/main overview + standalone about. Do not reorder relative to other 0N-*.css files. */
/* ── Wallets Overview Section ── */
.wallets-overview-section {
  margin-top: 14px;
  overflow: hidden;
  transition: all 0.3s ease-in-out;
  display: none; /* Hidden by default, shown only in expense tab */
  width: 100%;
  max-width: var(--content-max);
  margin-left: auto;
  margin-right: auto;
  box-sizing: border-box;
}

.wallets-overview-section.collapsed {
  margin-bottom: 0;
}

.wallets-overview-section .overview-top {
  cursor: pointer;
  user-select: none;
}

.wallets-overview-section .overview-top:hover {
  background: var(--panel-2);
}

.wallets-content {
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  transition: max-height 0.4s ease-in-out, opacity 0.3s ease-in-out, padding 0.3s ease-in-out;
}

.wallets-overview-section.expanded .wallets-content {
  max-height: 5000px;
  opacity: 1;
  padding-top: 14px;
}

.wallets-overview-section #expenseOverviewWallets {
  display: grid;
  gap: 10px;
}

/* Increase text size for summary card - keep title same, increase other texts */

.wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview .summary-line {
  font-size: 1.15em;
}

.wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview .summary-line-one {
  font-size: 1.2em;
}

.wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview .summary-line-one-label {
  font-size: 1.1em;
}

.wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview .summary-line-one-value {
  font-size: 1.1em;
}

.wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview .overview-card-actions {
  font-size: 1.05em;
}

/* Currency separator lines for premium appearance */
.wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview .currency-separator {
  height: 1px;
  background: linear-gradient(90deg, 
    transparent 0%, 
    var(--line) 15%, 
    var(--line) 85%, 
    transparent 100%
  );
  margin: 12px 20px 8px 20px;
  opacity: 0.6;
}

/* Desktop layout: split into two columns - left for summary, right for wallet cards */
@media (min-width: 769px) {
  .wallets-desktop-layout {
    display: grid;
    grid-template-columns: 320px 1fr;
    gap: 20px;
    align-items: start;
  }
  
  .summary-column {
    display: flex;
    flex-direction: column;
  }
  
  .wallets-column {
    display: flex;
    flex-direction: column;
  }
  
  .wallets-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 10px;
    align-content: start;
  }
  
  .wallets-full-width {
    width: 100%;
  }
}

/* Force 2 columns on mobile for wallet cards */
@media (max-width: 768px) {
  .wallets-overview-section #expenseOverviewWallets {
    display: grid !important;
    grid-template-columns: repeat(2, 1fr) !important;
    gap: 8px !important;
  }
  
  /* Summary card spans full width on mobile */
  .wallets-overview-section #expenseOverviewWallets .summary.currency-summary.expense-overview {
    grid-column: 1 / -1 !important;
    width: 100% !important;
  }
  
  /* Ensure wallet cards use single column */
  .wallets-overview-section #expenseOverviewWallets .summary.currency-summary:not(.expense-overview) {
    grid-column: auto !important;
    width: 100% !important;
  }
  
  /* Bitcoin summary grid responsive adjustments */
  .btc-summary-grid {
    grid-template-columns: repeat(2, 1fr) !important;
    gap: 8px !important;
  }
  
  .btc-summary-grid .summary div[id$="Value"] {
    font-size: 0.85rem !important;
    word-break: break-all !important;
    overflow-wrap: break-word !important;
    min-width: 0 !important;
    line-height: 1.2 !important;
  }
  
  /* Bitcoin transaction row styling */
  .btc-transaction-row {
    transition: background-color 0.2s ease;
  }
  
  .btc-transaction-row:hover {
    background-color: var(--panel-2);
  }
  
  .btc-transaction-details {
    border-bottom: 1px solid var(--line);
  }
  
  .btc-transaction-details .loan-details {
    animation: slideDown 0.2s ease-out;
  }
  
  @keyframes slideDown {
    from {
      opacity: 0;
      transform: translateY(-10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

.wallets-overview-section .icon-btn {
  transition: transform 0.3s ease-in-out;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.wallets-overview-section .icon-btn:hover {
  background: transparent !important;
  transform: rotate(180deg) translateY(-1px);
}

.wallets-overview-section.expanded .icon-btn {
  transform: rotate(180deg);
}

/* ── Main Overview Section ── */
.main-overview-section {
  overflow: hidden;
  transition: all 0.3s ease-in-out;
  width: 100%;
  max-width: var(--content-max);
  margin-left: auto;
  margin-right: auto;
  box-sizing: border-box;
}

.main-overview-section.collapsed {
  margin-bottom: 0;
}

.main-overview-section .overview-top {
  cursor: pointer;
  user-select: none;
}

.main-overview-section .overview-top:hover {
  background: var(--panel-2);
}

.main-overview-content {
  max-height: 1000px;
  overflow: hidden;
  opacity: 1;
  transition: max-height 0.4s ease-in-out, opacity 0.3s ease-in-out, padding 0.3s ease-in-out;
  padding-top: 14px;
}

.main-overview-section.collapsed .main-overview-content {
  max-height: 0;
  opacity: 0;
  padding-top: 0;
}

.main-overview-section .icon-btn {
  transition: transform 0.3s ease-in-out;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.main-overview-section .icon-btn:hover {
  background: transparent !important;
  transform: rotate(180deg) translateY(-1px);
}

.main-overview-section.collapsed .icon-btn {
  transform: rotate(0deg);
}

/* Expense sections collapsible styles */
.expense-section {
  margin-bottom: 14px;
}

.expense-section.collapsed {
  margin-bottom: 0;
}

.expense-section-content {
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: max-height 0.4s ease-in-out, opacity 0.3s ease-in-out, padding 0.3s ease-in-out;
}

.expense-section.expanded .expense-section-content {
  max-height: 5000px;
  opacity: 1;
  padding-top: 14px;
}

.expense-section .icon-btn {
  transition: transform 0.3s ease-in-out;
}

.expense-section.expanded .icon-btn {
  transform: rotate(180deg);
}

