/* ── Mobile: wallet boxes — 3 per row, last row fills ── */
@media (max-width: 560px) {
  .expense-wallet-scroll {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 5px;
  }
  .expense-wallet-card-wrap {
    flex: unset;
    min-width: unset;
    max-width: unset;
  }
  /* 1 item in last row → full width */
  .expense-wallet-card-wrap:last-child:nth-child(3n+1) {
    grid-column: 1 / -1;
  }
  /* 2 items in last row → last spans 2 cols */
  .expense-wallet-card-wrap:last-child:nth-child(3n+2) {
    grid-column: span 2;
  }
  .expense-wallet-card {
    min-width: unset;
    max-width: unset;
    padding: 6px 7px;
    gap: 4px;
  }
  .expense-wallet-title { font-size: .75rem; }
  .expense-wallet-sub { font-size: .62rem; }
  .expense-wallet-stats { font-size: .6rem; }
  .expense-wallet-actions { gap: 4px 8px; padding-top: 4px; margin-top: 3px; }
  .expense-wallet-actions button { font-size: .62rem; }
}
#expensesPanel .expense-wallet-block {
  display: none !important;
}

.floating-circles{
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
  isolation: isolate;
}

.floating-circles .circle{
  position: absolute;
  border-radius: 50%;
  opacity: 0.96;
  filter: blur(1.8px) saturate(1.35) contrast(1.05);
  transform: translate3d(0,0,0);
  will-change: transform, opacity;
  animation: floatMove 18s ease-in-out infinite alternate;
  background:
    radial-gradient(circle at 30% 30%,
      rgba(255,255,255,0.95) 0%,
      rgba(255,255,255,0.45) 18%,
      rgba(255,255,255,0.12) 34%,
      rgba(255,255,255,0.00) 52%),
    radial-gradient(circle at 70% 75%,
      var(--circle-color, rgba(255,105,180,0.55)) 0%,
      rgba(0,0,0,0.04) 65%,
      rgba(0,0,0,0.16) 100%);
  box-shadow:
    inset -12px -12px 24px rgba(0,0,0,0.10),
    inset 10px 10px 22px rgba(255,255,255,0.32),
    0 12px 28px rgba(0,0,0,0.14),
    0 0 22px rgba(255,255,255,0.10);
}

.circle:nth-child(1){
  width: 180px;
  height: 180px;
  top: 10%;
  left: 15%;
  --circle-color: rgba(255,105,180,0.62);
  animation-duration: 20s;
  animation-delay: 0s;
}

.circle:nth-child(2){
  width: 90px;
  height: 90px;
  top: 50%;
  left: 25%;
  --circle-color: rgba(0,191,255,0.62);
  animation-duration: 17s;
  animation-delay: -2s;
}

.circle:nth-child(3){
  width: 150px;
  height: 150px;
  top: 30%;
  left: 70%;
  --circle-color: rgba(255,20,147,0.64);
  animation-duration: 22s;
  animation-delay: -5s;
}

.circle:nth-child(4){
  width: 100px;
  height: 100px;
  top: 80%;
  left: 40%;
  --circle-color: rgba(30,144,255,0.62);
  animation-duration: 19s;
  animation-delay: -1s;
}

.circle:nth-child(5){
  width: 80px;
  height: 80px;
  top: 60%;
  left: 80%;
  --circle-color: rgba(255,182,193,0.66);
  animation-duration: 16s;
  animation-delay: -4s;
}

.circle:nth-child(6){
  width: 110px;
  height: 110px;
  top: 18%;
  left: 55%;
  --circle-color: rgba(0,255,200,0.48);
  animation-duration: 21s;
  animation-delay: -3s;
}

.circle:nth-child(7){
  width: 70px;
  height: 70px;
  top: 72%;
  left: 12%;
  --circle-color: rgba(255,180,0,0.48);
  animation-duration: 15s;
  animation-delay: -6s;
}

.circle:nth-child(8){
  width: 130px;
  height: 130px;
  top: 8%;
  left: 82%;
  --circle-color: rgba(180,110,255,0.52);
  animation-duration: 23s;
  animation-delay: -2.5s;
}

.circle:nth-child(9){
  width: 95px;
  height: 95px;
  top: 84%;
  left: 68%;
  --circle-color: rgba(255,90,120,0.54);
  animation-duration: 18s;
  animation-delay: -7s;
}

@keyframes floatMove{
  0%{
    transform: translate3d(0, 0, 0) scale(1);
  }
  25%{
    transform: translate3d(80px, -40px, 0) scale(1.08);
  }
  50%{
    transform: translate3d(-60px, 90px, 0) scale(0.94);
  }
  75%{
    transform: translate3d(50px, -70px, 0) scale(1.12);
  }
  100%{
    transform: translate3d(-30px, 30px, 0) scale(1.02);
  }
}

/* Standalone About Section Styles */
.standalone-about-section {
