  flex: 1 1 auto;
  min-width: 0;
}

.pw-eye-btn {
  appearance: none;
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  padding: 0;
  display: inline-grid;
  place-items: center;
  border-radius: 10px;
  border: 1px solid var(--line-strong);
  background: rgba(255, 255, 255, 0.82);
  color: var(--muted);
  cursor: pointer;
  transition: background .15s ease, color .15s ease, border-color .15s ease;
}

.pw-eye-btn:hover:not(:disabled) {
  color: var(--primary);
  border-color: rgba(36, 87, 214, 0.35);
  background: var(--primary-soft);
}

.pw-eye-btn:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.pw-eye-btn.is-visible {
  color: var(--primary);
  border-color: rgba(36, 87, 214, 0.4);
  background: var(--primary-soft);
}

.pw-eye-btn i {
  font-size: 0.92rem;
  line-height: 1;
  pointer-events: none;
}

.pw-eye-btn--input {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 32px;
  height: 32px;
  border: none;
  background: transparent;
  color: var(--muted);
}

.pw-eye-btn--input:hover:not(:disabled),
.pw-eye-btn--input.is-visible {
  background: transparent;
  border: none;
  color: var(--primary);
}

.btn.tiny {
