/* Admin Analytics overlay */
#adminAnalyticsModal.modal{ z-index: 9620; }
.admin-analytics-dialog{
  width: min(960px, calc(100vw - 24px));
  max-width: calc(100vw - 24px);
  max-height: calc(100vh - 24px);
