  overflow: hidden;
}
.admin-analytics-body{
  display: grid;
  gap: 10px;
  max-height: calc(100vh - 140px);
  overflow: auto;
  padding-right: 2px;
}
.admin-analytics-toolbar{
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.admin-analytics-ranges{
