/* ==========================================================================\n   Floating personal messages + viewport-fit conversation workspace\n   ========================================================================== */
#messagesPanel.active .messages-section{
  display:flex;
  flex-direction:column;
  height:clamp(560px, calc(100dvh - 184px), 820px);
  min-height:0;
  overflow:hidden;
}
#messagesPanel.active .messages-section > .section-head{
  flex:0 0 auto;
}
#messagesPanel.active .messages-compose{
  flex:0 0 auto;
  max-height:min(42dvh, 390px);
  overflow:auto;
  scrollbar-width:none;
}
#messagesPanel.active .messages-compose::-webkit-scrollbar{display:none;}
#messagesPanel.active .messages-workspace{
  flex:1 1 auto;
  height:auto;
  min-height:0;
}
#messagesPanel.active .messages-sidebar,
#messagesPanel.active .messages-conversation,
#messagesPanel.active .messages-thread-active{
  min-height:0;
  height:100%;
}
#messagesPanel.active .messages-thread-header{
  flex:0 0 auto;
  max-height:38%;
  overflow:auto;
  scrollbar-width:none;
}
#messagesPanel.active .messages-thread-header::-webkit-scrollbar{display:none;}
#messagesPanel.active .messages-chat-scroll{
  flex:1 1 auto;
  min-height:0;
  overflow:auto;
  overscroll-behavior:contain;
  scroll-behavior:smooth;
}
#messagesPanel.active .messages-reply-bar{
  flex:0 0 auto;
  position:relative;
  z-index:2;
}

.message-float-dock{
  position:fixed;
  right:18px;
  bottom:max(18px, calc(env(safe-area-inset-bottom, 0px) + 12px));
  z-index:9460;
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  gap:10px;
  pointer-events:none;
  font-family:inherit;
}
.message-float-dock.hide{display:none !important;}
.message-float-stack{
  display:flex;
  flex-direction:column-reverse;
  align-items:flex-end;
  gap:10px;
  pointer-events:auto;
}
.message-float-bubble{
  position:relative;
  width:58px;
  height:58px;
  min-width:58px;
  padding:0;
  border:1px solid color-mix(in srgb, var(--primary) 44%, rgba(255,255,255,.7));
  border-radius:50%;
  display:grid;
  place-items:center;
  cursor:pointer;
  color:#fff;
  background:
    radial-gradient(circle at 28% 20%, rgba(255,255,255,.58), transparent 26%),
    linear-gradient(145deg, color-mix(in srgb, var(--primary) 76%, #ffffff 24%), var(--primary));
  box-shadow:0 14px 34px color-mix(in srgb, var(--primary) 28%, rgba(15,23,42,.22)), inset 0 1px 0 rgba(255,255,255,.64);
  backdrop-filter:blur(16px) saturate(1.22);
  -webkit-backdrop-filter:blur(16px) saturate(1.22);
  transition:transform .2s ease, box-shadow .2s ease, filter .2s ease;
  animation:messageFloatIn .28s cubic-bezier(.2,.8,.2,1) both;
  overflow:visible;
}
.message-float-bubble:hover,
.message-float-bubble:focus-visible{
  transform:translateY(-2px) scale(1.045);
  box-shadow:0 18px 42px color-mix(in srgb, var(--primary) 34%, rgba(15,23,42,.26)), inset 0 1px 0 rgba(255,255,255,.7);
  outline:none;
}
.message-float-bubble.active{transform:scale(1.06);}
.message-float-bubble .message-float-avatar{
  width:100%;
  height:100%;
  border-radius:50%;
  display:grid;
  place-items:center;
  font-size:1.08rem;
  font-weight:800;
  letter-spacing:.02em;
  text-shadow:0 1px 8px rgba(0,0,0,.16);
}
.message-float-count{
  position:absolute;
  top:-3px;
  right:-3px;
  min-width:20px;
  height:20px;
  padding:0 5px;
  border-radius:999px;
  display:grid;
  place-items:center;
  background:var(--danger, #dc2626);
  color:#fff;
  border:2px solid color-mix(in srgb, var(--surface-elevated, #fff) 88%, transparent);
  font-size:.66rem;
  font-weight:800;
  line-height:1;
  box-shadow:0 3px 10px rgba(15,23,42,.2);
}
.message-float-card,
.message-float-peek{
  width:min(344px, calc(100vw - 28px));
  pointer-events:auto;
  color:var(--text);
  border:1px solid color-mix(in srgb, var(--line) 82%, transparent);
  background:var(--surface-glass-strong, rgba(255,255,255,.94));
  box-shadow:0 22px 56px rgba(15,23,42,.2), inset 0 1px 0 rgba(255,255,255,.52);
  backdrop-filter:blur(24px) saturate(1.2);
  -webkit-backdrop-filter:blur(24px) saturate(1.2);
}
.message-float-card{
  border-radius:20px;
  padding:12px;
  transform-origin:bottom right;
  animation:messageFloatCardIn .22s cubic-bezier(.2,.8,.2,1) both;
}
.message-float-card.hide,
.message-float-peek.hide{display:none !important;}
.message-float-card-head{
  display:grid;
  grid-template-columns:42px minmax(0,1fr) 32px;
  align-items:center;
  gap:9px;
}
.message-float-card-head > .message-float-avatar{
  width:42px;
  height:42px;
  border-radius:50%;
  display:grid;
  place-items:center;
  color:#fff;
  font-weight:800;
  background:linear-gradient(145deg, color-mix(in srgb, var(--primary) 72%, #fff 28%), var(--primary));
  box-shadow:0 8px 18px color-mix(in srgb, var(--primary) 20%, transparent);
}
.message-float-person{min-width:0;display:grid;gap:2px;}
.message-float-person strong{
  font-size:.88rem;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.message-float-person span{
  color:var(--muted);
  font-size:.71rem;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.message-float-icon-btn{
  width:32px;
  height:32px;
  border:0;
  border-radius:50%;
  display:grid;
  place-items:center;
  background:var(--surface-soft);
  color:var(--muted);
  cursor:pointer;
}
.message-float-icon-btn:hover{color:var(--text);background:var(--primary-soft);}
.message-float-message{
  margin:10px 0;
  padding:10px 11px;
  border:1px solid color-mix(in srgb, var(--line) 72%, transparent);
  border-radius:14px 14px 14px 5px;
  background:var(--surface-soft);
  font-size:.84rem;
  line-height:1.45;
  white-space:pre-wrap;
  word-break:break-word;
  max-height:112px;
  overflow:auto;
  scrollbar-width:none;
}
.message-float-message::-webkit-scrollbar{display:none;}
.message-float-reply{display:grid;gap:8px;}
.message-float-reply textarea{
  min-height:50px;
  max-height:112px;
  resize:none;
  font-size:.84rem;
  line-height:1.4;
}
.message-float-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:7px;
}
.message-float-actions .btn{font-size:.75rem;padding:7px 10px;min-height:34px;}
.message-float-peek{
  border-radius:16px;
  overflow:hidden;
  animation:messageFloatPeekIn .24s cubic-bezier(.2,.8,.2,1) both;
}
.message-float-peek-button{
  width:100%;
  border:0;
  padding:10px 12px;
  text-align:left;
  color:inherit;
  background:transparent;
  cursor:pointer;
}
.message-float-peek-button:hover{background:var(--primary-soft);}
.message-float-peek-copy{display:grid;gap:2px;min-width:0;}
.message-float-peek-copy strong{font-size:.82rem;}
.message-float-peek-copy span{
  color:var(--muted);
  font-size:.75rem;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
@keyframes messageFloatIn{
  from{opacity:0;transform:translateY(12px) scale(.82)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
@keyframes messageFloatCardIn{
  from{opacity:0;transform:translateY(9px) scale(.96)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
@keyframes messageFloatPeekIn{
  from{opacity:0;transform:translateX(12px)}
  to{opacity:1;transform:translateX(0)}
}

@media (max-width:900px){
  #messagesPanel.active .messages-section{
    height:clamp(500px, calc(100dvh - 132px), 760px);
  }
  #messagesPanel.active .messages-workspace,
  #messagesPanel.active .messages-sidebar,
  #messagesPanel.active .messages-workspace.messages-conversation-open .messages-conversation{
    min-height:0 !important;
    height:100% !important;
  }
  #messagesPanel.active .messages-workspace.messages-conversation-open .messages-thread-active{
    min-height:0;
