/* ========================================================================== */
/* 2026-08-30 Messenger motion + desktop scroll freedom refinement.            */
/* ========================================================================== */
.message-float-dock,
.message-float-head{
  will-change:transform;
}
.message-float-bubble .message-float-avatar{
  overflow:hidden;
  padding:5px;
}
.message-float-bubble .message-float-avatar img{
  width:100%;
  height:100%;
  display:block;
  object-fit:contain;
  border-radius:50%;
  pointer-events:none;
  user-select:none;
  -webkit-user-drag:none;
  filter:drop-shadow(0 3px 8px rgba(15,23,42,.14));
}
.message-float-head-close{
  position:absolute;
  z-index:8;
  top:-5px;
  right:-5px;
  width:23px;
  height:23px;
  padding:0;
  border-radius:50%;
  display:grid;
  place-items:center;
  border:1px solid color-mix(in srgb, var(--danger, #dc2626) 38%, var(--line));
  color:#fff;
  background:color-mix(in srgb, var(--danger, #dc2626) 88%, #111827 12%);
  box-shadow:0 6px 16px rgba(15,23,42,.24);
  cursor:pointer;
  font-size:.62rem;
  opacity:0;
  transform:scale(.68) rotate(-14deg);
  pointer-events:none;
  transition:opacity .14s ease, transform .18s cubic-bezier(.2,.8,.2,1), box-shadow .16s ease;
}
.message-float-head-close:hover,
.message-float-head-close:focus-visible{
  box-shadow:0 8px 20px color-mix(in srgb, var(--danger, #dc2626) 30%, rgba(15,23,42,.22));
  outline:none;
}
@media (min-width:901px){
  .message-float-head:hover .message-float-head-close,
  .message-float-head:focus-within .message-float-head-close{
    opacity:1;
    transform:scale(1) rotate(0deg);
    pointer-events:auto;
  }
  .message-float-head:hover .message-float-count,
  .message-float-head:focus-within .message-float-count{
    opacity:0;
    transform:scale(.72);
  }
  /* Desktop quick chat is floating, not modal. Background remains manually scrollable. */
  html.message-float-page-locked-root,
  body.message-float-page-locked{
    overscroll-behavior:auto !important;
  }
}
.message-float-count{
  transition:opacity .14s ease, transform .14s ease;
}
.message-float-dock.dragging .message-float-bubble{
  transform:scale(1.075);
  filter:saturate(1.08) brightness(1.035);
  box-shadow:0 22px 48px color-mix(in srgb, var(--primary) 34%, rgba(15,23,42,.3)), inset 0 1px 0 rgba(255,255,255,.76);
}
.message-float-dock.is-gliding,
