  pointer-events:none;
}
.message-float-dock.is-gliding .message-float-bubble,
.message-float-head.is-gliding .message-float-bubble{
  filter:saturate(1.06) brightness(1.02);
  box-shadow:0 18px 40px color-mix(in srgb, var(--primary) 30%, rgba(15,23,42,.26)), inset 0 1px 0 rgba(255,255,255,.7);
}
@media (max-width:900px){
  .message-float-head-close{display:none !important;}
}
@media (prefers-reduced-motion:reduce){
  .message-float-head-close,
