/* ===== 13-assets.css ===== */
/* Asset Management panel + detail overlays */
.assets-list {
  display: grid;
  gap: 6px;
}

.asset-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 8px;
  background: var(--card, #fff);
  transition: border-color .15s ease, box-shadow .15s ease;
}

.asset-card:hover,
