  justify-content: space-between;
  gap: 6px;
  align-items: center;
}

.asset-card-main {
  appearance: none;
  border: 0;
  background: transparent;
  padding: 0;
  margin: 0;
  text-align: left;
  cursor: pointer;
  font: inherit;
  color: inherit;
  min-width: 0;
  flex: 1 1 auto;
}

.asset-card-title {
  margin: 0;
  font-size: .78rem;
  font-weight: 650;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.asset-card-meta {
  display: flex;
  flex-wrap: nowrap;
  gap: 4px 6px;
  align-items: center;
