  align-items: center;
  padding: 0 5px;
  border-radius: 999px;
  font-size: .58rem;
  font-weight: 700;
  letter-spacing: .01em;
  line-height: 1.45;
  background: #eef2ff;
  color: #3730a3;
  flex: 0 0 auto;
  max-width: none !important;
}

.asset-status-active { background: #ecfdf5; color: #047857; }
.asset-status-sold { background: #eff6ff; color: #1d4ed8; }
.asset-status-disposed { background: #f3f4f6; color: #4b5563; }

.asset-card-aside {
