  margin-bottom: 0;
  font-weight: 650;
  line-height: 1;
}

.asset-card-net strong {
  font-size: .72rem;
  font-weight: 700;
  line-height: 1.15;
  white-space: nowrap;
}

.asset-net-profit strong { color: #15803d; }
.asset-net-loss strong { color: #b91c1c; }
.asset-net-flat strong { color: var(--text); }

.asset-card-stats {
  appearance: none;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 2px 6px;
  margin-top: 5px;
  padding-top: 5px;
  border-top: 1px solid color-mix(in srgb, var(--line) 80%, transparent);
  font-size: .62rem;
  width: 100%;
  border-left: 0;
  border-right: 0;
  border-bottom: 0;
