  }
  .asset-detail-dialog {
    width: calc(100vw - 12px);
    max-width: calc(100vw - 12px);
    max-height: min(90dvh, calc(100% - max(8px, env(safe-area-inset-top, 0px)) - 12px));
    border-radius: 12px;
  }
  .asset-detail-dialog .modal-head {
    padding: 8px 10px 4px;
  }
  .asset-detail-dialog .modal-head h3 {
