/* ── Depreciation Assets module (additive; independent of P/L assets) ── */
.assets-module-tabs {
  display: flex;
  gap: 4px;
  padding: 0 0 10px;
  margin: 0 0 4px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}

.assets-module-tab {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--muted);
  font: inherit;
  font-size: .78rem;
  font-weight: 650;
  padding: 6px 10px;
  border-radius: 8px;
  cursor: pointer;
  line-height: 1.2;
}

.assets-module-tab:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--accent, #0ea5e9) 8%, transparent);
}

.assets-module-tab.is-active {
  color: var(--text);
  background: color-mix(in srgb, var(--accent, #0ea5e9) 14%, transparent);
}

.assets-module-view.hide {
  display: none !important;
}

.dep-assets-summary {
  margin: 8px 0 10px;
}

.dep-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.dep-summary-card {
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
  background: var(--card, #fff);
  min-width: 0;
}

.dep-summary-card small {
  display: block;
  color: var(--muted);
  font-size: .62rem;
  font-weight: 650;
  margin-bottom: 2px;
}

.dep-summary-card strong {
  font-size: .88rem;
  font-weight: 700;
  line-height: 1.2;
  word-break: break-word;
}

.dep-summary-note {
  margin: 6px 0 0;
  font-size: .68rem;
}

.dep-assets-list {
  display: grid;
  gap: 6px;
}

.dep-form-preview {
  margin-top: 10px;
  padding: 8px 10px;
  border: 1px dashed var(--line);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent, #0ea5e9) 4%, transparent);
}

.dep-preview-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 8px;
}

.dep-preview-grid small {
  display: block;
  color: var(--muted);
  font-size: .6rem;
  font-weight: 650;
}

.dep-preview-grid strong {
  font-size: .78rem;
}

.dep-kpi-grid {
  margin-bottom: 10px;
}

.dep-history-title {
  margin: 14px 0 8px;
  font-size: .85rem;
}

.dep-history-table-wrap {
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.dep-history-table {
  width: 100%;
  border-collapse: collapse;
  font-size: .72rem;
}

.dep-history-table th,
.dep-history-table td {
  padding: 6px 8px;
  text-align: left;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}

.dep-history-table th {
  background: color-mix(in srgb, var(--accent, #0ea5e9) 6%, transparent);
  font-weight: 700;
  font-size: .65rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: .02em;
}

.dep-history-table tr:last-child td {
  border-bottom: 0;
}

@media (max-width: 720px) {
  .dep-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 480px) {
  .assets-module-tabs {
    gap: 2px;
  }
  .assets-module-tab {
    font-size: .72rem;
    padding: 5px 8px;
  }
  .dep-summary-grid {
    grid-template-columns: 1fr 1fr;
  }
}


/* ===== 14-shared-card-surface.css ===== */
/* Shared soft card surface + accent orb — matches Dashboard hero cards site-wide.
   Loaded last so it wins over per-section flat white card backgrounds. */

:root{
  --triplem-card-accent:#60a5fa;
  /* Soft rotating orb palette for multi-card lists */
  --triplem-orb-1:#60a5fa; /* light blue */
  --triplem-orb-2:#f9a8d4; /* light pink */
  --triplem-orb-3:#fb7185; /* light rose */
  --triplem-orb-4:#c4b5fd; /* soft violet */
  --triplem-orb-5:#5eead4; /* soft mint */
  --triplem-orb-6:#fdba74; /* soft peach */
}

/* Section shell accents stay soft; list cards get rotating orbs below */
#expensesPanel > .card.section,
#dashboardPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-1); }
#goodsPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-1); }
#assetsPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-5); }
#givenPanel > .card.section,
#receivedPanel > .card.section,
#takenPanel > .card.section,
#returnedPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-2); }
#installmentsPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-3); }
#notesPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-4); }
#bitcoinPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-6); }
#messagesPanel > .card.section,
#adminPanel > .card.section{ --triplem-card-accent:var(--triplem-orb-1); }

/* Soft semantic accents for dashboard hero / blocks (overridden by cycle when siblings) */
.dashboard-block.is-expenses{ --triplem-card-accent:var(--triplem-orb-1); }
.dashboard-block.is-inventory{ --triplem-card-accent:#38bdf8; }
.dashboard-block.is-assets{ --triplem-card-accent:var(--triplem-orb-5); }
.dashboard-block.is-loans{ --triplem-card-accent:var(--triplem-orb-2); }
.dashboard-block.is-installments{ --triplem-card-accent:var(--triplem-orb-3); }

.card.section,
.dashboard-block,
.loan,
.installment-plan-card,
.asset-card,
.dep-asset-card,
.dep-summary-card,
.expense-wallet-card,
.inventory-section-card,
.inventory-sku-card,
.inventory-draft-card,
.summary.currency-summary,
.asset-kpi,
.ip-metric,
.dep-preview-grid > div,
.section-details-metric,
.section-details-chart-card,
.btc-wallet-card,
.btc-wallet-details,
.landing-surface-card,
#notesList > .card{
  --triplem-card-accent:var(--triplem-card-accent, var(--triplem-orb-1));
  position:relative;
  border:1px solid rgba(208,213,221,.72);
  border-radius:14px;
  /* Soft wash + corner orb via backgrounds only (no ::after / no child z-index = menus stay on top) */
  background:
    radial-gradient(88px 88px at 100% 100%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 22%, transparent), transparent 72%),
    radial-gradient(120% 90% at 100% 0%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 12%, transparent), transparent 55%),
    linear-gradient(160deg, rgba(255,255,255,.99), rgba(252,253,255,.94));
  box-shadow:0 6px 16px rgba(15,23,42,.03);
}

/* Section shells keep a slightly larger corner glow */
.card.section,
.dashboard-block{
  background:
    radial-gradient(130px 130px at 100% 100%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 18%, transparent), transparent 72%),
    radial-gradient(120% 90% at 100% 0%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 10%, transparent), transparent 55%),
    linear-gradient(160deg, rgba(255,255,255,.99), rgba(252,253,255,.94));
}

/* Compact metric tiles */
.asset-kpi,
.ip-metric,
.dep-summary-card,
.section-details-metric{
  background:
    radial-gradient(52px 52px at 100% 100%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 22%, transparent), transparent 72%),
    radial-gradient(120% 90% at 100% 0%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 10%, transparent), transparent 55%),
    linear-gradient(160deg, rgba(255,255,255,.99), rgba(252,253,255,.94));
}

/* Installment menus need overflow visible; other list cards keep sensible clipping */
.installment-plan-card{
  overflow:visible;
}
.loan:not(.installment-plan-card),
.asset-card,
.dep-asset-card,
.expense-wallet-card,
.inventory-section-card,
.inventory-sku-card,
.summary.currency-summary,
.dashboard-block,
.card.section{
  overflow:hidden;
}

/* Inner fillers were solid white — let the shared surface show through */
.installment-plan-card .ip-card,
.loan .loan-top,
.loan .ip-card{
  background:transparent;
}
.loan-top:hover{
  background:rgba(248,250,252,.55);
}
.loan .detail{
  background:rgba(248,250,252,.42);
}
.asset-card-main,
.asset-card-stats,
.asset-card-aside{
  background:transparent;
}

/* Preserve dashed “add” inventory tile (don’t force filled surface) */
.inventory-section-add-card{
  background:rgba(248,250,252,.55);
  box-shadow:none;
}

/* Selected wallet still reads clearly on the soft surface */
.expense-wallet-radio:checked + .expense-wallet-card{
  border-color:rgba(36,87,214,.5);
  background:
    radial-gradient(120% 90% at 100% 0%, rgba(36,87,214,.10), transparent 55%),
    linear-gradient(160deg, rgba(239,246,255,.98), rgba(248,250,255,.94));
  box-shadow:0 0 0 2px rgba(36,87,214,.08);
}

/* Hover polish aligned with dashboard cards */
