/* ── Main tabs banner (sticky nav) ─────────────────────────────────────── */
.tabs{
  position:sticky;
  overflow:hidden;
  border:1px solid rgba(208,213,221,.72);
  border-radius:16px;
  background:
    radial-gradient(100px 100px at 100% 100%, rgba(96,165,250,.18), transparent 72%),
    radial-gradient(120% 90% at 100% 0%, rgba(37,99,235,.08), transparent 55%),
    linear-gradient(160deg, rgba(255,255,255,.99), rgba(248,250,252,.94));
  box-shadow:0 8px 22px rgba(15,23,42,.05);
  backdrop-filter:blur(8px);
  z-index:30;
}
.tabs::after{
  display:none;
}
.tabs > .tab{
  position:relative;
  z-index:1;
}
.tab:hover:not(:disabled):not(.guest-disabled){
  color:var(--text);
  background:rgba(37,99,235,.07);
}
.tab.active{
  color:#fff;
  background:
    linear-gradient(160deg, #3b82f6, #2563eb 55%, #1d4ed8);
  box-shadow:0 6px 16px rgba(37,99,235,.22);
}
.tab.active:hover:not(:disabled){
  color:#fff;
  background:
    linear-gradient(160deg, #60a5fa, #2563eb 50%, #1d4ed8);
}
.tab:disabled,
.tab.guest-disabled{
  background:rgba(248,250,252,.72);
}

/* Secondary in-section tab strips (Loans mode / Assets modules) */
.loan-mode-switch,
.assets-module-tabs{
  position:relative;
  overflow:hidden;
  border:1px solid rgba(208,213,221,.72);
  border-radius:14px;
  background:
    radial-gradient(72px 72px at 100% 100%, rgba(96,165,250,.16), transparent 72%),
    radial-gradient(120% 90% at 100% 0%, rgba(37,99,235,.07), transparent 55%),
    linear-gradient(160deg, rgba(255,255,255,.99), rgba(248,250,252,.94));
  box-shadow:0 4px 14px rgba(15,23,42,.03);
}
.assets-module-tabs{
  padding:4px;
  margin:0 0 10px;
  border-bottom:1px solid rgba(208,213,221,.72);
  width:fit-content;
  max-width:100%;
}
.loan-mode-switch::after,
.assets-module-tabs::after{
  display:none;
}
.loan-mode-btn.active{
  background:
    linear-gradient(160deg, #3b82f6, #2563eb 55%, #1d4ed8);
  color:#fff;
  border-color:transparent;
  box-shadow:0 4px 12px rgba(37,99,235,.2);
}
.loan-mode-btn.active:hover{
  color:#fff;
}
.assets-module-tab.is-active{
  color:#fff;
  background:
    linear-gradient(160deg, #3b82f6, #2563eb 55%, #1d4ed8);
  box-shadow:0 4px 12px rgba(37,99,235,.2);
}

