/* ===== 15-seo-pages.css ===== */
/* Triplem VIP SEO pages + homepage crawlable pillar (additive)
   Premium glass / motion system aligned with the main sign-in landing. */

:root{
  --seo-ink:#0f172a;
  --seo-muted:#475569;
  --seo-line:#dbe3ef;
  --seo-bg:#edf1f7;
  --seo-card:#ffffff;
  --seo-accent:#2457d6;
  --seo-accent-soft:#e8effc;
  --seo-orb-1:#60a5fa;
  --seo-orb-2:#5eead4;
  --seo-orb-3:#fdba74;
  --seo-orb-4:#f9a8d4;
}

/* ── Homepage pillar (embedded in landing) ──────────────────────────────── */
.landing-seo-pillar{
  margin: 1.25rem 0 0.35rem;
  padding: 1.35rem 1.2rem 1.2rem;
  border-radius: 18px;
  background:
    radial-gradient(120% 80% at 0% 0%, rgba(36,87,214,.08), transparent 55%),
    linear-gradient(180deg, #fff 0%, #f7f9fc 100%);
  border: 1px solid var(--seo-line);
}
.landing-seo-pillar-head{
  max-width: 46rem;
  margin-bottom: 1rem;
}
.landing-seo-pillar-head h2{
  margin: .2rem 0 .55rem;
  font-size: clamp(1.25rem, 2.4vw, 1.65rem);
  line-height: 1.25;
  color: var(--seo-ink);
}
.landing-seo-pillar-head p{
  margin: 0;
  color: var(--seo-muted);
  line-height: 1.55;
  font-size: .95rem;
}
.landing-seo-pillar-grid{
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: .75rem;
}
.landing-seo-pillar-more{
  margin: .95rem 0 0;
  font-size: .88rem;
  color: var(--seo-muted);
}
.landing-seo-pillar-more a{
  color: var(--seo-accent);
  font-weight: 600;
  text-decoration: none;
}
.landing-seo-pillar-more a:hover,
.landing-seo-pillar-more a:focus-visible{
  text-decoration: underline;
}

@media (max-width: 960px){
  .landing-seo-pillar-grid{ grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 560px){
  .landing-seo-pillar{ padding: 1.1rem 1rem; }
  .landing-seo-pillar-grid{ grid-template-columns: 1fr; }
}

/* ── Standalone SEO topic pages ─────────────────────────────────────────── */
.seo-page{
  margin: 0;
  min-height: 100vh;
  color: var(--seo-ink);
  isolation: isolate;
  background:
    radial-gradient(90% 60% at 100% -10%, rgba(36,87,214,.14), transparent 50%),
    radial-gradient(70% 50% at 0% 100%, rgba(94,234,212,.12), transparent 45%),
    linear-gradient(165deg, #eef2f8 0%, #e8eef8 42%, #f3f6fb 100%);
  font-family: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  scroll-behavior: smooth;
}
.seo-page::before,
.seo-page::after{
  content:"";
  position:fixed;
  pointer-events:none;
  z-index:0;
  border-radius:50%;
  filter:blur(42px);
  opacity:.5;
  animation:seoOrbFloat 18s ease-in-out infinite;
}
.seo-page::before{
  width:min(420px, 70vw);
  height:min(420px, 70vw);
  top:-10%;
  right:-12%;
  background:radial-gradient(circle, rgba(36,87,214,.2), transparent 70%);
}
.seo-page::after{
  width:min(360px, 65vw);
  height:min(360px, 65vw);
  bottom:4%;
  left:-14%;
  background:radial-gradient(circle, rgba(94,234,212,.18), transparent 70%);
  animation-delay:-7s;
}
@keyframes seoOrbFloat{
  0%, 100%{ transform:translate3d(0,0,0) scale(1); }
  50%{ transform:translate3d(0, 16px, 0) scale(1.05); }
}

.seo-wrap{
  position:relative;
  z-index:1;
  width: min(920px, calc(100% - 2rem));
  margin: 0 auto;
  padding: 1rem 0 3rem;
}

/* Sticky glass nav */
.seo-nav{
  position:sticky;
  top:12px;
  z-index:40;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
  padding: .7rem .85rem;
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,.72);
  background: linear-gradient(160deg, rgba(255,255,255,.78), rgba(248,250,252,.62));
  box-shadow: 0 14px 36px rgba(15,23,42,.08);
  backdrop-filter: blur(18px) saturate(1.2);
  -webkit-backdrop-filter: blur(18px) saturate(1.2);
}
