/* Sticky trial ticker + sprinkle loop */
.seo-offer-ticker{
  position:sticky;
  top:86px;
  z-index:35;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  flex-wrap:wrap;
  margin: 0 0 1rem;
  padding:8px 12px;
  border-radius:14px;
  border:1px solid rgba(220,38,38,.22);
  background:linear-gradient(135deg, rgba(254,242,242,.94), rgba(255,247,237,.9));
  box-shadow:
    0 10px 28px rgba(220,38,38,.1),
    0 0 0 1px rgba(255,255,255,.35) inset;
  backdrop-filter:blur(12px) saturate(1.1);
  -webkit-backdrop-filter:blur(12px) saturate(1.1);
  text-align:center;
  overflow:hidden;
  isolation:isolate;
}
.seo-offer-ticker::after{
  content:"";
  position:absolute;
  inset:-20% -40%;
  pointer-events:none;
  z-index:0;
  background:linear-gradient(
    105deg,
    transparent 35%,
    rgba(255,255,255,.55) 48%,
    rgba(253,224,71,.28) 52%,
    transparent 65%
  );
  transform:translate3d(-60%, 0, 0) skewX(-12deg);
  animation:seoOfferShimmer 4s ease-in-out infinite;
}
@keyframes seoOfferShimmer{
  0%, 55%{ transform:translate3d(-60%, 0, 0) skewX(-12deg); opacity:0; }
  60%{ opacity:.85; }
  78%{ transform:translate3d(60%, 0, 0) skewX(-12deg); opacity:.35; }
  85%, 100%{ transform:translate3d(70%, 0, 0) skewX(-12deg); opacity:0; }
}
.seo-offer-sprinkles{
  position:absolute;
  inset:0;
  pointer-events:none;
  overflow:hidden;
  z-index:0;
}
.seo-offer-ticker-pulse,
.seo-offer-ticker-text,
.seo-offer-ticker-cta{
  position:relative;
  z-index:1;
}
.seo-offer-ticker-pulse{
  color:#dc2626;
  font-size:.55rem;
  line-height:1;
  animation:seoOfferBlink 1.1s ease-in-out infinite;
}
.seo-offer-ticker-text{
  margin:0;
  color:#7f1d1d;
  font-size:.78rem;
  font-weight:650;
