  animation:seoOfferBlink 1.4s ease-in-out infinite;
}
.seo-offer-ticker-cta:hover{ color:#991b1b; }
@keyframes seoOfferBlink{
  0%, 100%{ opacity:1; }
  50%{ opacity:.35; }
}
.seo-offer-sprinkle{
  position:absolute;
  width:5px;
  height:5px;
  border-radius:50%;
  background:radial-gradient(circle, #fde68a 0%, #f59e0b 55%, transparent 70%);
  box-shadow:0 0 6px rgba(245,158,11,.55);
  opacity:0;
  animation:seoOfferSprinkle 3.6s ease-in-out infinite;
}
.seo-offer-sprinkle:nth-child(1){ left:8%;  top:70%; animation-delay:0s; }
.seo-offer-sprinkle:nth-child(2){ left:22%; top:80%; animation-delay:.45s; width:4px; height:4px; }
.seo-offer-sprinkle:nth-child(3){ left:38%; top:65%; animation-delay:.9s; }
.seo-offer-sprinkle:nth-child(4){ left:52%; top:78%; animation-delay:1.25s; width:3px; height:3px; }
.seo-offer-sprinkle:nth-child(5){ left:66%; top:68%; animation-delay:1.7s; background:radial-gradient(circle, #fecaca 0%, #ef4444 55%, transparent 70%); box-shadow:0 0 6px rgba(239,68,68,.45); }
.seo-offer-sprinkle:nth-child(6){ left:78%; top:82%; animation-delay:2.1s; width:4px; height:4px; }
.seo-offer-sprinkle:nth-child(7){ left:90%; top:70%; animation-delay:2.5s; }
.seo-offer-sprinkle:nth-child(8){ left:14%; top:75%; animation-delay:2.95s; width:3px; height:3px; background:radial-gradient(circle, #fff7ed 0%, #fb923c 55%, transparent 70%); }
@keyframes seoOfferSprinkle{
  0%, 12%{ opacity:0; transform:translate3d(0, 6px, 0) scale(.4); }
  28%{ opacity:.95; transform:translate3d(2px, -10px, 0) scale(1); }
  55%{ opacity:.55; transform:translate3d(-4px, -18px, 0) scale(.75) rotate(25deg); }
  78%, 100%{ opacity:0; transform:translate3d(6px, -28px, 0) scale(.2); }
}

