/* Scroll reveal — slow, dramatic; replays when re-entering view */
[data-seo-reveal]{
  opacity:0;
  transform:translate3d(0, 88px, 0) scale(.9);
  filter:blur(2px);
  transition:
    opacity .55s cubic-bezier(.4,0,.2,1),
    transform .55s cubic-bezier(.4,0,.2,1),
    filter .45s ease;
  will-change: opacity, transform, filter;
}
[data-seo-reveal].is-seo-revealed{
  opacity:1;
  transform:translate3d(0,0,0) scale(1);
  filter:blur(0);
  transition:
    opacity 1.45s cubic-bezier(.16,1,.3,1),
    transform 1.7s cubic-bezier(.16,1,.3,1),
    filter 1.35s ease;
}

/* Top sections: same effect, CSS starts on first paint (no JS wait) */
[data-seo-reveal][data-seo-reveal-eager]:not(.seo-reveal-ready){
  opacity:1;
  transform:none;
  filter:none;
  transition:none;
  animation:seoRevealBoot 1.45s cubic-bezier(.16,1,.3,1) both;
}
[data-seo-reveal][data-seo-reveal-eager]:not(.seo-reveal-ready) [data-seo-stagger] > *{
  opacity:1;
  transform:none;
  filter:none;
  transition:none;
}
@keyframes seoRevealBoot{
  from{
    opacity:0;
    transform:translate3d(0, 88px, 0) scale(.9);
    filter:blur(2px);
  }
  to{
    opacity:1;
    transform:translate3d(0,0,0) scale(1);
    filter:blur(0);
  }
}
[data-seo-reveal][data-seo-reveal-eager].seo-reveal-ready{
  animation:none;
}
[data-seo-stagger] > *{
  opacity:0;
  transform:translate3d(0, 56px, 0) scale(.92);
  filter:blur(1px);
  transition:
    opacity .45s cubic-bezier(.4,0,.2,1),
    transform .45s cubic-bezier(.4,0,.2,1),
    filter .35s ease;
}
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *:nth-child(1){ transition-delay:.08s; }
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *:nth-child(2){ transition-delay:.2s; }
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *:nth-child(3){ transition-delay:.32s; }
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *:nth-child(4){ transition-delay:.44s; }
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *:nth-child(5){ transition-delay:.56s; }
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *:nth-child(6){ transition-delay:.68s; }
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > *{
  opacity:1;
  transform:translate3d(0,0,0) scale(1);
  filter:blur(0);
  transition:
    opacity 1.25s cubic-bezier(.16,1,.3,1),
    transform 1.45s cubic-bezier(.16,1,.3,1),
    filter 1.15s ease;
}
/* Keep hover lift after reveal */
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > .seo-card:hover,
[data-seo-reveal].is-seo-revealed [data-seo-stagger] > a.seo-card:hover{
  transform: translate3d(0, -4px, 0);
}

@media (max-width: 960px){
  .seo-offer-ticker{ top:78px; }
}
@media (max-width: 720px){
  .seo-nav{ flex-direction: column; align-items: flex-start; }
  .seo-nav-links{ justify-content: flex-start; }
  .seo-grid-2{ grid-template-columns: 1fr; }
  .seo-hero{ padding: 1.25rem 1.05rem; }
  .seo-offer-ticker{
    gap:6px;
    padding:7px 10px;
    top:118px;
  }
  .seo-offer-ticker-text{ font-size:.7rem; }
  .seo-offer-ticker-cta{ font-size:.68rem; }
  [data-seo-reveal]{
    transform:translate3d(0, 56px, 0) scale(.93);
    filter:blur(1.5px);
  }
  [data-seo-stagger] > *{
    transform:translate3d(0, 36px, 0) scale(.94);
  }
  .seo-page::before,
  .seo-page::after{
    filter:blur(32px);
    opacity:.38;
  }
}

@media (prefers-reduced-motion: reduce){
  .seo-page{ scroll-behavior:auto; }
  .seo-page::before,
  .seo-page::after,
  .seo-offer-sprinkle,
  .seo-offer-ticker::after,
  .seo-offer-ticker-pulse,
  .seo-offer-ticker-cta,
  [data-seo-reveal][data-seo-reveal-eager],
  [data-seo-reveal],
  [data-seo-stagger] > *,
  .seo-card,
  .seo-btn,
  .seo-related a,
  .seo-card-icon{
    animation:none !important;
    transition:none !important;
    opacity:1 !important;
    transform:none !important;
    filter:none !important;
  }
  .seo-offer-sprinkle{ opacity:0 !important; }
}


/* Founder-parity optical tags for search guides */
.seo-kicker,.seo-related a,.seo-offer-ticker{
  position:relative;
  isolation:isolate;
  overflow:hidden;
  backdrop-filter:blur(12px) saturate(1.16);
  -webkit-backdrop-filter:blur(12px) saturate(1.16);
}
.seo-kicker{
  width:max-content;
  max-width:100%;
  padding:.34rem .66rem;
  border-radius:999px;
  border:1px solid rgba(255,255,255,.76);
  background:linear-gradient(145deg,rgba(255,255,255,.70),rgba(232,239,252,.40));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.86),0 7px 18px rgba(36,87,214,.08);
}
.seo-kicker::after,.seo-related a::after,.seo-offer-ticker::before{
  content:"";
  position:absolute;
  z-index:0;
  top:-55%;
  left:112%;
  width:34%;
  height:210%;
  transform:rotate(17deg);
  pointer-events:none;
  opacity:.46;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.84),rgba(255,255,255,.16),transparent);
  animation:seoLensSweepRtl 9.2s cubic-bezier(.22,.65,.32,1) infinite;
}
.seo-related a::after{animation-delay:calc(var(--seo-chip-index,0) * .22s);opacity:.34;}
.seo-kicker > *,.seo-related a > *,.seo-offer-ticker > *{position:relative;z-index:1;}
@keyframes seoLensSweepRtl{0%,69%,100%{left:112%}80%{left:-42%}}
.seo-search-questions{margin-top:1rem;}
.seo-search-questions h2{margin-top:0;}
.seo-search-questions h3{margin:.95rem 0 .28rem;font-size:1rem;line-height:1.3;}
