/* ===== 16-admin-security.css ===== */
/* Admin Security Key — lock gate + compact settings overlay */

#adminPanel{
  position: relative;
}

.admin-security-lock{
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 1.5rem 1rem 2rem;
  background:
    radial-gradient(90% 70% at 50% 0%, color-mix(in srgb,var(--primary,#2457d6) 14%,transparent), transparent 58%),
    color-mix(in srgb,var(--bg,#edf1f7) 90%,transparent);
  backdrop-filter: blur(18px) saturate(1.04);
  -webkit-backdrop-filter: blur(18px) saturate(1.04);
}

/* Keep Messenger heads perceptually behind the Admin key gate instead of
   visually colliding with the keypad/card. Navigation itself remains usable. */
body:has(#adminSecurityLock:not(.hide):not([hidden])) .message-float-dock{
  opacity:.14;
  filter:blur(9px) saturate(.72);
  pointer-events:none !important;
  transition:opacity .18s ease, filter .18s ease;
}

.admin-security-lock.hide,
.admin-panel-content.hide{
  display: none !important;
}

.admin-security-lock-card{
  width: min(420px, 100%);
  margin-top: 1.25rem;
  padding: 1.6rem 1.35rem 1.4rem;
  border-radius: 18px;
  background: linear-gradient(155deg,var(--surface-glass-strong,#fff),var(--surface-glass,#fff));
  border: 1px solid var(--glass-border,var(--line,#dbe3ef));
  box-shadow: var(--shadow-strong,0 18px 40px rgba(15,23,42,.08));
  text-align: center;
}

.admin-security-lock-icon{
  width: 64px;
  height: 64px;
  margin: 0 auto .85rem;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: var(--primary-soft,#e8effc);
  color: var(--primary,#2457d6);
  font-size: 1.45rem;
}

.admin-security-lock-card h3{
  margin: 0 0 .45rem;
  font-size: 1.2rem;
  color: var(--text, #0f172a);
}

.admin-security-lock-lead{
  margin: 0 0 1rem;
  color: var(--muted, #64748b);
  font-size: .92rem;
  line-height: 1.45;
}

.admin-security-lock-card .form-label{
  display: block;
  text-align: left;
  margin-bottom: .35rem;
}

.admin-security-key-input{
  letter-spacing: .12em;
  font-variant-numeric: tabular-nums;
  text-align: center;
  font-size: .86rem;
}

.admin-security-error{
  min-height: 1.15em;
  margin: .45rem 0 0;
  color: #b42318;
  font-size: .82rem;
  line-height: 1.35;
}

.admin-security-lock-card .admin-security-error{
  text-align: center;
  margin: .65rem 0 .35rem;
}

.admin-security-status{
  margin: .2rem 0 0;
  color: #027a48;
  font-size: .78rem;
  line-height: 1.35;
}

/* Compact create/change key overlay — matches admin settings-sheet */
#adminSecurityKeyModal.modal{
  z-index: 9400;
  padding: 16px;
  place-items: center;
}

#adminSecurityKeyModal .modal-dialog.admin-security-key-dialog{
  --triplem-card-accent: var(--triplem-orb-2, #60a5fa);
  width: min(360px, calc(100vw - 32px)) !important;
  max-width: calc(100vw - 32px);
  max-height: calc(100vh - 32px);
  margin: 0 auto;
  border-radius: 16px;
  overflow: hidden;
}

#adminSecurityKeyModal .settings-sheet-head{
  padding: 12px 14px 8px;
}

#adminSecurityKeyModal .settings-sheet-head h3{
  font-size: .95rem;
}

#adminSecurityKeyModal .settings-sheet-head p{
  font-size: .72rem;
  margin-top: 2px;
}

#adminSecurityKeyModal .settings-sheet-body{
  padding: 10px 12px 12px !important;
  gap: 8px;
  max-height: calc(100vh - 88px);
}

#adminSecurityKeyModal .admin-security-key-fields{
  display: grid;
  gap: 8px;
}

#adminSecurityKeyModal .admin-security-key-fields .field{
  display: grid;
  gap: 4px;
  margin: 0;
}

#adminSecurityKeyModal .form-label{
  margin: 0;
  font-size: .72rem;
  font-weight: 700;
  color: var(--muted, #64748b);
}

#adminSecurityKeyModal .admin-security-optional{
