  opacity: .85;
}

#adminSecurityKeyModal .input.admin-security-key-input{
  min-height: 36px;
  height: 36px;
  padding: 0 10px;
  font-size: .95rem;
}

#adminSecurityKeyModal .settings-sheet-footer{
  margin-top: 4px;
  gap: 8px;
}

#adminSecurityKeyModal .settings-sheet-footer .btn{
