/* ===== 17-landing-motion.css ===== */
/* Premium Apple-style landing / sign-in page motion + shared cards.
   UI-only. Does not affect auth, APIs, or business logic. */

/* ── Ambient depth (keeps existing .lock::before glass flow) ────────────── */

.landing-cta--public{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  color:#344054;
  background:rgba(255,255,255,.58);
  border-color:rgba(183,193,208,.72);
  box-shadow:0 8px 20px rgba(15,23,42,.06);
}
.landing-cta--public:hover{
  color:var(--primary);
  border-color:color-mix(in srgb,var(--primary) 38%,rgba(183,193,208,.72));
  background:rgba(255,255,255,.82);
}
.landing-cta--public:focus-visible{
  outline:0;
  box-shadow:0 0 0 4px rgba(36,87,214,.17),0 8px 20px rgba(15,23,42,.08);
}
#lockScreen.lock{
  isolation:isolate;
}
/* Soft floating orb via ::after only — do not override .lock::before */
#lockScreen.lock::after{
  content:"";
  position:fixed;
  pointer-events:none;
  z-index:0;
  width:min(380px, 70vw);
  height:min(380px, 70vw);
  bottom:6%;
  left:-14%;
  border-radius:50%;
  background:radial-gradient(circle, rgba(94,234,212,.2), transparent 70%);
  filter:blur(40px);
  opacity:.5;
  animation:landingOrbFloat 20s ease-in-out infinite;
}
#lockScreen .landing-shell{
  position:relative;
  z-index:1;
}
#lockScreen .landing-shell::before{
  content:"";
  position:absolute;
  pointer-events:none;
  z-index:0;
  width:min(320px, 55vw);
  height:min(320px, 55vw);
  top:12%;
  right:-8%;
  border-radius:50%;
  background:radial-gradient(circle, rgba(36,87,214,.14), transparent 70%);
  filter:blur(36px);
  opacity:.55;
  animation:landingOrbFloat 16s ease-in-out infinite reverse;
}
@keyframes landingOrbFloat{
  0%, 100%{ transform:translate3d(0,0,0) scale(1); }
  50%{ transform:translate3d(0, 16px, 0) scale(1.05); }
}
/* Fixed orb must not paint over the app when landing is dismissed */
#lockScreen.lock.hide::after{
  display:none !important;
}

/* ── Shared glass card system ───────────────────────────────────────────── */
.landing-surface-card{
  --triplem-card-accent:var(--triplem-orb-1, #60a5fa);
  position:relative;
  border:1px solid rgba(255,255,255,.72) !important;
  background:
    radial-gradient(100px 90px at 100% 100%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 20%, transparent), transparent 72%),
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--triplem-card-accent,#60a5fa) 10%, transparent), transparent 55%),
    linear-gradient(160deg, rgba(255,255,255,.82), rgba(248,250,252,.68)) !important;
  box-shadow:
    0 10px 28px rgba(15,23,42,.06),
    inset 0 1px 0 rgba(255,255,255,.75) !important;
  backdrop-filter:blur(14px) saturate(1.15);
  -webkit-backdrop-filter:blur(14px) saturate(1.15);
  transition:
    transform .42s cubic-bezier(.22,1,.36,1),
    box-shadow .42s ease,
    border-color .35s ease,
    background .35s ease;
  will-change:transform;
}
.landing-convince-card.landing-surface-card:nth-child(1),
.landing-seo-card.landing-surface-card:nth-child(1),
.landing-demo-chart-card.landing-surface-card:nth-child(1),
.landing-testimonial.landing-surface-card:nth-child(1){ --triplem-card-accent:var(--triplem-orb-1,#60a5fa); }
.landing-convince-card.landing-surface-card:nth-child(2),
.landing-seo-card.landing-surface-card:nth-child(2),
.landing-demo-chart-card.landing-surface-card:nth-child(2),
.landing-testimonial.landing-surface-card:nth-child(2){ --triplem-card-accent:var(--triplem-orb-5,#5eead4); }
.landing-convince-card.landing-surface-card:nth-child(3),
.landing-seo-card.landing-surface-card:nth-child(3),
.landing-demo-chart-card.landing-surface-card:nth-child(3),
.landing-testimonial.landing-surface-card:nth-child(3){ --triplem-card-accent:var(--triplem-orb-6,#fdba74); }
.landing-convince-card.landing-surface-card:nth-child(4),
.landing-seo-card.landing-surface-card:nth-child(4),
.landing-demo-chart-card.landing-surface-card:nth-child(4),
.landing-testimonial.landing-surface-card:nth-child(4){ --triplem-card-accent:var(--triplem-orb-2,#f9a8d4); }
.landing-trial-banner-card.landing-surface-card{ --triplem-card-accent:var(--triplem-orb-5,#5eead4); }

.landing-surface-card:hover,
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > .landing-surface-card:hover,
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > a.landing-seo-card:hover{
  transform:translate3d(0,-5px,0);
  border-color:color-mix(in srgb, var(--triplem-card-accent,#2563eb) 38%, rgba(255,255,255,.72)) !important;
  box-shadow:
    0 18px 40px rgba(15,23,42,.1),
    inset 0 1px 0 rgba(255,255,255,.85) !important;
}
.landing-surface-card:active,
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > .landing-surface-card:active,
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > a.landing-seo-card:active{
  transform:translate3d(0,-2px,0) scale(.985);
}

/* Glass panel shells */
.landing-trial-banner-inner,
.landing-seo-pillar{
  border:1px solid rgba(255,255,255,.7) !important;
  background:
    radial-gradient(120% 90% at 0% 0%, rgba(36,87,214,.08), transparent 55%),
    linear-gradient(165deg, rgba(255,255,255,.78), rgba(244,247,252,.62)) !important;
  backdrop-filter:blur(16px) saturate(1.12);
  -webkit-backdrop-filter:blur(16px) saturate(1.12);
  box-shadow:0 16px 40px rgba(15,23,42,.07) !important;
}

/* ── Scroll reveal (slow, dramatic; replays when re-entering view) ──────── */
[data-landing-reveal]{
  opacity:0;
  transform:translate3d(0, 88px, 0) scale(.9);
  filter:blur(2px);
  /* Faster settle when leaving view so the next reveal can play cleanly */
  transition:
    opacity .55s cubic-bezier(.4,0,.2,1),
    transform .55s cubic-bezier(.4,0,.2,1),
    filter .45s ease;
  will-change:opacity, transform, filter;
}
[data-landing-reveal].is-landing-revealed{
  opacity:1;
  transform:translate3d(0,0,0) scale(1);
  filter:blur(0);
  transition:
    opacity 1.45s cubic-bezier(.16,1,.3,1),
    transform 1.7s cubic-bezier(.16,1,.3,1),
    filter 1.35s ease;
}

/* Top sections: same effect, but CSS starts it on first paint (no JS wait) */
[data-landing-reveal][data-landing-reveal-eager]:not(.landing-reveal-ready){
  opacity:1;
  transform:none;
  filter:none;
  transition:none;
  animation:landingRevealBoot 1.45s cubic-bezier(.16,1,.3,1) both;
}
[data-landing-reveal][data-landing-reveal-eager]:not(.landing-reveal-ready) [data-landing-stagger] > *{
  opacity:1;
  transform:none;
  filter:none;
  transition:none;
}
@keyframes landingRevealBoot{
  from{
    opacity:0;
    transform:translate3d(0, 88px, 0) scale(.9);
    filter:blur(2px);
  }
  to{
    opacity:1;
    transform:translate3d(0,0,0) scale(1);
    filter:blur(0);
  }
}
[data-landing-reveal][data-landing-reveal-eager].landing-reveal-ready{
  animation:none;
}
[data-landing-stagger] > *{
  opacity:0;
  transform:translate3d(0, 56px, 0) scale(.92);
  filter:blur(1px);
  transition:
    opacity .45s cubic-bezier(.4,0,.2,1),
    transform .45s cubic-bezier(.4,0,.2,1),
    filter .35s ease;
  will-change:opacity, transform, filter;
}
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > *:nth-child(1){ transition-delay:.08s; }
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > *:nth-child(2){ transition-delay:.2s; }
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > *:nth-child(3){ transition-delay:.32s; }
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > *:nth-child(4){ transition-delay:.44s; }
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > *:nth-child(5){ transition-delay:.56s; }
[data-landing-reveal].is-landing-revealed [data-landing-stagger] > *{
  opacity:1;
  transform:translate3d(0,0,0) scale(1);
  filter:blur(0);
  transition:
    opacity 1.25s cubic-bezier(.16,1,.3,1),
    transform 1.45s cubic-bezier(.16,1,.3,1),
    filter 1.15s ease;
}

/* Hero parallax (driven by JS, GPU-friendly) */
[data-landing-parallax] .landing-hero-marketing-inner{
  will-change:transform, opacity;
  transform:translateZ(0);
}

/* ── Professional icon system + hover motion ────────────────────────────── */
.landing-hero-trust{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:6px 8px;
}
.landing-hero-trust > span{
  display:inline-flex;
  align-items:center;
  gap:5px;
}
.landing-hero-trust i{
  color:#2457d6;
  font-size:.78rem;
  transition:transform .28s cubic-bezier(.22,1,.36,1), color .28s ease;
}
.landing-hero-trust > span:hover i{
  transform:translateY(-1px) scale(1.12);
  color:#1d4ed8;
}
.landing-hero-trust-sep{ opacity:.45; }
/* Sticky trial ticker — stays under the landing nav while scrolling */
.landing-offer-ticker{
  position:sticky;
  top:86px;
  z-index:28;
  overflow:hidden;
  isolation:isolate;
  backdrop-filter:blur(12px) saturate(1.1);
  -webkit-backdrop-filter:blur(12px) saturate(1.1);
  box-shadow:
    0 10px 28px rgba(220,38,38,.1),
    0 0 0 1px rgba(255,255,255,.35) inset;
}
.landing-offer-ticker::after{
  content:"";
  position:absolute;
  inset:-20% -40%;
  pointer-events:none;
  z-index:0;
  background:linear-gradient(
    105deg,
    transparent 35%,
    rgba(255,255,255,.55) 48%,
    rgba(253,224,71,.28) 52%,
    transparent 65%
  );
  transform:translate3d(-60%, 0, 0) skewX(-12deg);
  animation:landingOfferShimmer 4s ease-in-out infinite;
}
@keyframes landingOfferShimmer{
  0%, 55%{ transform:translate3d(-60%, 0, 0) skewX(-12deg); opacity:0; }
  60%{ opacity:.85; }
  78%{ transform:translate3d(60%, 0, 0) skewX(-12deg); opacity:.35; }
  85%, 100%{ transform:translate3d(70%, 0, 0) skewX(-12deg); opacity:0; }
}
.landing-offer-ticker-text strong i{
  margin-right:4px;
  color:#ea580c;
}

/* Looping sprinkle / sparkle burst */
.landing-offer-sprinkles{
  position:absolute;
  inset:0;
  pointer-events:none;
  overflow:hidden;
  z-index:0;
}
.landing-offer-ticker-pulse,
.landing-offer-ticker-text,
.landing-offer-ticker-cta{
  position:relative;
  z-index:1;
}
.landing-offer-sprinkle{
  position:absolute;
  width:5px;
  height:5px;
  border-radius:50%;
  background:radial-gradient(circle, #fde68a 0%, #f59e0b 55%, transparent 70%);
  box-shadow:0 0 6px rgba(245,158,11,.55);
  opacity:0;
  animation:landingOfferSprinkle 3.6s ease-in-out infinite;
}
.landing-offer-sprinkle:nth-child(1){ left:8%;  top:70%; animation-delay:0s; }
.landing-offer-sprinkle:nth-child(2){ left:22%; top:80%; animation-delay:.45s; width:4px; height:4px; }
.landing-offer-sprinkle:nth-child(3){ left:38%; top:65%; animation-delay:.9s; }
.landing-offer-sprinkle:nth-child(4){ left:52%; top:78%; animation-delay:1.25s; width:3px; height:3px; }
.landing-offer-sprinkle:nth-child(5){ left:66%; top:68%; animation-delay:1.7s; background:radial-gradient(circle, #fecaca 0%, #ef4444 55%, transparent 70%); box-shadow:0 0 6px rgba(239,68,68,.45); }
.landing-offer-sprinkle:nth-child(6){ left:78%; top:82%; animation-delay:2.1s; width:4px; height:4px; }
.landing-offer-sprinkle:nth-child(7){ left:90%; top:70%; animation-delay:2.5s; }
.landing-offer-sprinkle:nth-child(8){ left:14%; top:75%; animation-delay:2.95s; width:3px; height:3px; background:radial-gradient(circle, #fff7ed 0%, #fb923c 55%, transparent 70%); }
@keyframes landingOfferSprinkle{
  0%, 12%{
    opacity:0;
    transform:translate3d(0, 6px, 0) scale(.4);
  }
  28%{
    opacity:.95;
    transform:translate3d(2px, -10px, 0) scale(1);
  }
  55%{
    opacity:.55;
    transform:translate3d(-4px, -18px, 0) scale(.75) rotate(25deg);
  }
  78%, 100%{
    opacity:0;
    transform:translate3d(6px, -28px, 0) scale(.2);
  }
}
@media (max-width: 960px){
  .landing-offer-ticker{ top:78px; }
}
@media (prefers-reduced-motion: reduce){
  .landing-offer-sprinkle,
  .landing-offer-ticker::after{
    animation:none !important;
    opacity:0 !important;
  }
}
.landing-trial-points li{
  display:flex;
