  #lockScreen.lock::after,
  #lockScreen .landing-shell::before,
  [data-landing-parallax] .landing-hero-marketing-inner{
    opacity:1 !important;
    transform:none !important;
    filter:none !important;
    transition:none !important;
    animation:none !important;
  }
}

/* ========================================================================== 
   Landing 2026 refresh: full-width desktop stage, compact proof surfaces,
   manual notice controls, search-intent content, and low-cost rendering.
   ========================================================================== */
#lockScreen .landing-shell{
  width:calc(100% - clamp(24px, 3.2vw, 64px));
  max-width:none;
  padding:clamp(12px,1.4vw,20px) 0 30px;
}
#lockScreen .landing-nav{
  width:min(100%, 1600px);
  margin-inline:auto;
  border-radius:20px;
  background:rgba(255,255,255,.58);
  box-shadow:0 18px 50px rgba(15,23,42,.09), inset 0 1px 0 rgba(255,255,255,.76);
}
#lockScreen .landing-main--marketing,
#lockScreen .landing-main:has(.landing-hero-marketing){
  gap:clamp(16px,2vw,26px);
}
#lockScreen .landing-main--marketing > *,
#lockScreen .landing-main:has(.landing-hero-marketing) > *{
  width:100%;
  max-width:1480px;
}
#lockScreen .landing-shell:has(.landing-main--marketing) > .landing-demo-analytics,
#lockScreen .landing-shell:has(.landing-main--marketing) > .landing-testimonials,
#lockScreen .landing-shell:has(.landing-main--marketing) > .landing-footer{
  width:100%;
  max-width:1480px;
  margin-inline:auto;
}

/* Premium full-screen hero */
#lockScreen .landing-hero-marketing{
  position:relative;
  isolation:isolate;
  min-height:clamp(560px, calc(100svh - 150px), 820px);
  display:grid;
  grid-template-columns:minmax(0,1.02fr) minmax(420px,.98fr);
  align-items:center;
  gap:clamp(30px,5vw,80px);
  padding:clamp(34px,5vw,76px);
  overflow:hidden;
  border:1px solid rgba(255,255,255,.64);
  border-radius:clamp(24px,2.4vw,36px);
  background:
    radial-gradient(circle at 7% 13%, rgba(96,165,250,.16), transparent 31%),
    radial-gradient(circle at 88% 18%, rgba(94,234,212,.12), transparent 30%),
    linear-gradient(145deg, rgba(255,255,255,.68), rgba(248,250,252,.42));
  box-shadow:0 34px 88px rgba(15,23,42,.10), inset 0 1px 0 rgba(255,255,255,.82);
  backdrop-filter:blur(18px) saturate(1.08);
  -webkit-backdrop-filter:blur(18px) saturate(1.08);
}
#lockScreen .landing-hero-marketing::before{
  content:"";
  position:absolute;
  inset:-35% 48% 52% -16%;
  z-index:-1;
  border-radius:50%;
  background:linear-gradient(125deg, rgba(36,87,214,.12), rgba(255,255,255,.02));
  filter:blur(22px);
  pointer-events:none;
}
#lockScreen .landing-hero-marketing::after{
  content:"";
  position:absolute;
  width:42%;
  aspect-ratio:1;
  right:-15%;
  bottom:-38%;
  z-index:-1;
  border-radius:50%;
  background:rgba(94,234,212,.12);
  filter:blur(28px);
  pointer-events:none;
}
#lockScreen .landing-hero-marketing-inner{
  width:100%;
  max-width:720px;
  margin:0;
  text-align:left;
}
#lockScreen .landing-hero-marketing .landing-eyebrow{
  justify-content:flex-start;
  width:max-content;
  max-width:100%;
  margin-bottom:12px;
  padding:7px 11px;
  border:1px solid rgba(36,87,214,.13);
  border-radius:999px;
  background:rgba(255,255,255,.54);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.7);
}
#lockScreen .landing-hero-marketing .landing-hero-title{
  justify-items:start;
  margin:0;
  gap:11px;
}
#lockScreen .landing-hero-marketing .landing-brand-name{
  font-size:clamp(2.7rem,5vw,5rem);
  letter-spacing:.045em;
  line-height:.95;
}
#lockScreen .landing-hero-marketing .landing-tagline{
  max-width:26ch;
  margin:0;
  color:#334155;
  font-size:clamp(1.08rem,1.5vw,1.42rem);
  line-height:1.34;
  font-weight:650;
  letter-spacing:-.025em;
}
#lockScreen .landing-hero-marketing .landing-lead{
  max-width:60ch;
  margin:16px 0 0;
  color:#64748b;
  font-size:clamp(.92rem,1vw,1.02rem);
  line-height:1.65;
}
#lockScreen .landing-hero-marketing .landing-hero-actions{
  justify-content:flex-start;
  margin-top:20px;
  gap:8px;
}
#lockScreen .landing-hero-marketing .landing-hero-actions .btn{
  min-height:42px;
  padding:10px 14px;
  border-radius:13px;
}
#lockScreen .landing-hero-marketing .landing-hero-trust{
  justify-content:flex-start;
  margin-top:14px;
  color:#64748b;
  font-size:.78rem;
}

/* Manual trial / fraud overlay controls */
.landing-hero-info-actions{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:9px;
  max-width:610px;
  margin-top:14px;
}
.landing-info-action{
  appearance:none;
  min-width:0;
  display:grid;
  grid-template-columns:34px minmax(0,1fr) 16px;
  align-items:center;
  gap:9px;
  padding:9px 10px;
  text-align:left;
  color:#334155;
  border:1px solid rgba(148,163,184,.22);
  border-radius:14px;
  background:rgba(255,255,255,.52);
  box-shadow:0 8px 24px rgba(15,23,42,.05), inset 0 1px 0 rgba(255,255,255,.75);
  cursor:pointer;
  transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease,background .2s ease;
}
.landing-info-action:hover,
.landing-info-action:focus-visible{
  transform:translateY(-1px);
  border-color:rgba(36,87,214,.26);
  background:rgba(255,255,255,.72);
  box-shadow:0 12px 28px rgba(15,23,42,.08),inset 0 1px 0 rgba(255,255,255,.82);
}
.landing-info-action:focus-visible{outline:2px solid rgba(36,87,214,.38);outline-offset:2px;}
.landing-info-action-icon{
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  color:#2457d6;
  background:rgba(36,87,214,.09);
}
.landing-info-action--fraud .landing-info-action-icon{color:#b54708;background:rgba(245,158,11,.10);}
.landing-info-action strong,
.landing-info-action small{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.landing-info-action strong{font-size:.78rem;line-height:1.25;color:#1e293b;}
.landing-info-action small{margin-top:2px;font-size:.66rem;line-height:1.25;color:#64748b;}
.landing-info-action-arrow{font-size:.66rem;color:#94a3b8;}

/* Lightweight interface preview */
.landing-hero-showcase{
  width:100%;
  max-width:620px;
  justify-self:end;
  min-width:0;
}
.landing-showcase-window{
  position:relative;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.78);
  border-radius:26px;
  padding:15px;
  background:linear-gradient(145deg,rgba(255,255,255,.80),rgba(241,245,249,.62));
  box-shadow:0 30px 72px rgba(15,23,42,.14),inset 0 1px 0 rgba(255,255,255,.9);
  backdrop-filter:blur(16px) saturate(1.05);
  -webkit-backdrop-filter:blur(16px) saturate(1.05);
}
.landing-showcase-window::after{
  content:"";
  position:absolute;
  inset:-30% -55%;
  pointer-events:none;
  background:linear-gradient(108deg,transparent 42%,rgba(255,255,255,.65) 49%,rgba(96,165,250,.10) 52%,transparent 58%);
  transform:translateX(-40%) rotate(-4deg);
  animation:landingShowcaseLens 8s ease-in-out infinite;
}
@keyframes landingShowcaseLens{
  0%,62%{transform:translateX(-42%) rotate(-4deg);opacity:0;}
  68%{opacity:.75;}
  82%{transform:translateX(42%) rotate(-4deg);opacity:.2;}
  88%,100%{transform:translateX(46%) rotate(-4deg);opacity:0;}
}
.landing-showcase-head,
.landing-showcase-ledger-head,
.landing-showcase-row,
.landing-showcase-footer{position:relative;z-index:1;}
.landing-showcase-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;}
.landing-showcase-brand{display:flex;align-items:center;gap:8px;min-width:0;font-size:.78rem;font-weight:800;color:#1e293b;}
.landing-showcase-brand img{width:30px;height:30px;object-fit:contain;border-radius:9px;background:rgba(255,255,255,.75);padding:3px;}
.landing-showcase-live{display:inline-flex;align-items:center;gap:6px;padding:5px 8px;border-radius:999px;background:rgba(15,118,110,.07);color:#0f766e;font-size:.63rem;font-weight:750;white-space:nowrap;}
.landing-showcase-live i{width:6px;height:6px;border-radius:50%;background:#10b981;box-shadow:0 0 0 3px rgba(16,185,129,.12);}
.landing-showcase-metrics{position:relative;z-index:1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-bottom:10px;}
.landing-showcase-metrics article{min-width:0;padding:12px;border:1px solid rgba(148,163,184,.15);border-radius:15px;background:rgba(255,255,255,.58);box-shadow:inset 0 1px 0 rgba(255,255,255,.72);}
.landing-showcase-metrics small,.landing-showcase-metrics span{display:block;color:#64748b;}
.landing-showcase-metrics small{font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;}
.landing-showcase-metrics strong{display:block;margin:5px 0 2px;color:#0f172a;font-size:clamp(1rem,1.5vw,1.28rem);letter-spacing:-.03em;}
.landing-showcase-metrics span{font-size:.64rem;}
.landing-showcase-ledger{position:relative;z-index:1;padding:12px;border:1px solid rgba(148,163,184,.15);border-radius:16px;background:rgba(255,255,255,.52);}
.landing-showcase-ledger-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:8px;border-bottom:1px solid rgba(148,163,184,.14);font-size:.72rem;color:#1e293b;}
.landing-showcase-ledger-head span{font-size:.62rem;color:#94a3b8;}
.landing-showcase-row{display:grid;grid-template-columns:30px minmax(0,1fr) auto;gap:9px;align-items:center;padding:9px 0;border-bottom:1px solid rgba(148,163,184,.10);}
.landing-showcase-row:last-child{border-bottom:0;padding-bottom:1px;}
.landing-showcase-row-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:rgba(36,87,214,.07);color:#2457d6;font-size:.7rem;}
.landing-showcase-row strong,.landing-showcase-row small{display:block;}
.landing-showcase-row strong{font-size:.71rem;color:#334155;}
.landing-showcase-row small{margin-top:2px;font-size:.6rem;color:#94a3b8;}
.landing-showcase-row b{font-size:.69rem;color:#b42318;white-space:nowrap;}
.landing-showcase-row b.is-positive{color:#047857;}
.landing-showcase-footer{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin-top:10px;}
.landing-showcase-footer span{display:flex;align-items:center;justify-content:center;gap:5px;min-width:0;padding:7px 4px;border-radius:10px;background:rgba(36,87,214,.055);color:#475569;font-size:.59rem;font-weight:700;white-space:nowrap;}
.landing-showcase-footer i{color:#2457d6;font-size:.62rem;}
.landing-showcase-note{margin:8px 4px 0;text-align:center;color:#94a3b8;font-size:.61rem;}

/* Search-intent question section: visible, people-first content rather than rich-result stuffing. */
.landing-owner-questions{
  padding:clamp(24px,3.4vw,48px);
  border:1px solid rgba(255,255,255,.58);
  border-radius:26px;
  background:linear-gradient(145deg,rgba(255,255,255,.52),rgba(248,250,252,.30));
  box-shadow:0 22px 58px rgba(15,23,42,.06),inset 0 1px 0 rgba(255,255,255,.7);
}
.landing-owner-questions-head{max-width:760px;margin:0 auto 18px;text-align:center;}
.landing-owner-questions-head h2{margin:4px 0 8px;color:#0f172a;font-size:clamp(1.45rem,2.5vw,2.15rem);letter-spacing:-.035em;}
.landing-owner-questions-head > p:last-child{margin:0;color:#64748b;font-size:.88rem;line-height:1.55;}
.landing-owner-questions-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}
.landing-question-card{margin:0!important;padding:0!important;overflow:hidden;border-radius:16px!important;}
.landing-question-card summary{list-style:none;position:relative;padding:14px 42px 14px 15px;color:#1e293b;font-size:.82rem;font-weight:780;line-height:1.35;cursor:pointer;}
.landing-question-card summary::-webkit-details-marker{display:none;}
.landing-question-card summary::after{content:"+";position:absolute;top:50%;right:15px;transform:translateY(-50%);width:22px;height:22px;display:grid;place-items:center;border-radius:50%;background:rgba(36,87,214,.08);color:#2457d6;font-size:.9rem;font-weight:500;transition:transform .22s ease,background .22s ease;}
.landing-question-card[open] summary::after{content:"−";background:rgba(36,87,214,.13);}
.landing-question-card p{margin:0;padding:0 15px 14px;color:#64748b;font-size:.76rem;line-height:1.55;}
.landing-question-card[open]{border-color:rgba(36,87,214,.18)!important;box-shadow:0 12px 30px rgba(15,23,42,.06),inset 0 1px 0 rgba(255,255,255,.72)!important;}

