/* ===== 19-notes-workspace.css ===== */
/* Expenses photo menu stability + professional notes workspace. */

/* The photo trigger owns a fixed 18px box. Its menu is portaled to <body> while
   open, so neither the dropdown nor its animation can participate in card layout. */
.wallet-logo-menu-wrap{
  width:18px;
  height:18px;
  flex:0 0 18px;
  contain:layout style;
}
.wallet-logo-photo-btn{
  position:absolute;
  inset:0;
  margin:0;
  transform:none;
}
.wallet-logo-menu-dropdown[data-wallet-logo-portaled="true"]{
  position:fixed !important;
  right:auto !important;
  min-width:112px;
  max-width:min(180px, calc(100vw - 16px));
  margin:0;
  overflow:auto;
  overscroll-behavior:contain;
  z-index:13000 !important;
  transform-origin:top right;
  animation:wallet-photo-menu-in .16s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes wallet-photo-menu-in{
  from{opacity:0;transform:translateY(-4px) scale(.97)}
  to{opacity:1;transform:translateY(0) scale(1)}
}

/* Notes header */
.notes-section-head{
  margin-bottom:14px;
}
.notes-head-actions .btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  white-space:nowrap;
}

/* Notes grid */
#notesList.notes-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill, minmax(178px, 1fr));
  gap:12px;
  align-items:stretch;
  min-width:0;
}
#notesList > .note-grid-card{
  width:100%;
  height:148px;
  min-width:0;
  margin:0;
  padding:18px;
  display:flex;
  align-items:center;
  justify-content:center;
  text-align:center;
  color:var(--text);
  font:inherit;
  cursor:pointer;
  overflow:hidden;
  isolation:isolate;
  transition:transform .18s ease, border-color .18s ease, box-shadow .18s ease, background-color .18s ease;
}
#notesList > .note-grid-card:hover{
  transform:translateY(-2px);
  border-color:color-mix(in srgb, var(--triplem-card-accent, #8b5cf6) 45%, rgba(208,213,221,.72));
  box-shadow:0 12px 24px rgba(15,23,42,.08);
}
#notesList > .note-grid-card:focus-visible{
  outline:3px solid color-mix(in srgb, var(--primary, #2457d6) 26%, transparent);
  outline-offset:2px;
  border-color:var(--primary, #2457d6);
}
.note-grid-title{
  display:-webkit-box;
  -webkit-box-orient:vertical;
  -webkit-line-clamp:4;
  line-clamp:4;
  max-width:100%;
  max-height:5.6em;
  overflow:hidden;
  text-overflow:ellipsis;
  overflow-wrap:anywhere;
  word-break:break-word;
  font-size:.96rem;
  font-weight:760;
  line-height:1.4;
  letter-spacing:-.012em;
}
.notes-empty{
  grid-column:1 / -1;
  min-height:220px;
  padding:28px 18px;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:8px;
  border:1px dashed color-mix(in srgb, var(--line-strong, #cbd5e1) 78%, transparent);
  border-radius:14px;
  background:rgba(255,255,255,.58);
  text-align:center;
  color:var(--muted);
}
.notes-empty-icon{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:13px;
  background:color-mix(in srgb, var(--triplem-orb-4, #c4b5fd) 24%, #fff);
  color:#6d4bc3;
  font-size:1rem;
}
.notes-empty strong{color:var(--text);font-size:.94rem}
.notes-empty p{margin:0 0 5px;max-width:42ch;font-size:.82rem;line-height:1.5}

/* Notes overlays */
#noteCreateModal .modal-dialog,
#noteDetailModal .modal-dialog{--triplem-card-accent:var(--triplem-orb-4, #c4b5fd)}
.note-workspace-modal.modal{z-index:10800}
.note-workspace-modal .modal-backdrop{
  background:rgba(15,23,42,.54);
  backdrop-filter:blur(7px);
  -webkit-backdrop-filter:blur(7px);
}
.note-workspace-modal .modal-dialog{
  animation:note-workspace-modal-in .22s cubic-bezier(.2,.8,.2,1) both;
}
.note-create-dialog{width:min(640px, calc(100vw - 24px)) !important}
.note-detail-dialog{width:min(680px, calc(100vw - 24px)) !important}
@keyframes note-workspace-modal-in{
  from{opacity:0;transform:translateY(10px) scale(.985)}
  to{opacity:1;transform:translateY(0) scale(1)}
}
.note-create-grid{gap:12px}
.note-textarea{
  min-height:170px;
  resize:vertical;
  line-height:1.55;
}
.note-field-hint{
  margin-top:5px;
  color:var(--muted);
  font-size:.72rem;
  line-height:1.4;
}
.note-create-reminder-card{
  padding:0 !important;
  border:1px solid var(--line);
  border-radius:13px;
  background:rgba(255,255,255,.72);
  overflow:hidden;
}
.note-reminder-toggle{
  min-height:64px;
  margin:0;
  padding:11px 12px;
  display:flex;
  align-items:center;
  gap:10px;
  cursor:pointer;
}
.note-reminder-toggle-icon{
  width:34px;
  height:34px;
  flex:0 0 34px;
  display:grid;
  place-items:center;
  border-radius:10px;
  color:#6d4bc3;
  background:color-mix(in srgb, var(--triplem-orb-4, #c4b5fd) 24%, #fff);
}
.note-reminder-toggle-copy{min-width:0;flex:1;display:grid;gap:2px}
.note-reminder-toggle-copy strong{font-size:.84rem;color:var(--text)}
.note-reminder-toggle-copy small{font-size:.72rem;color:var(--muted);line-height:1.35}
.note-reminder-toggle input{
  position:absolute;
  width:1px;
  height:1px;
  opacity:0;
  pointer-events:none;
}
.note-toggle-control{
  position:relative;
  width:38px;
  height:22px;
  flex:0 0 38px;
  border-radius:999px;
  background:#d6dbe4;
  box-shadow:inset 0 0 0 1px rgba(15,23,42,.07);
  transition:background .18s ease;
}
.note-toggle-control::after{
  content:"";
  position:absolute;
  top:3px;
  left:3px;
  width:16px;
  height:16px;
  border-radius:50%;
  background:#fff;
  box-shadow:0 1px 4px rgba(15,23,42,.2);
  transition:transform .18s ease;
}
.note-reminder-toggle input:checked + .note-toggle-control{background:var(--primary, #2457d6)}
.note-reminder-toggle input:checked + .note-toggle-control::after{transform:translateX(16px)}
.note-reminder-toggle:has(input:focus-visible){outline:3px solid rgba(36,87,214,.18);outline-offset:-3px}
.note-reminder-toggle:has(input:disabled){cursor:not-allowed;opacity:.68}
.note-create-reminder-fields{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:10px;
  padding:11px 12px 12px;
  border-top:1px solid var(--line);
  background:rgba(248,250,252,.7);
}
.note-create-reminder-fields.hide{display:none}
.note-create-footer,
.note-edit-footer{
  display:flex;
  justify-content:flex-end;
  gap:8px;
}

/* Note detail and in-place editing */
.note-detail-heading{min-width:0;max-width:calc(100% - 42px)}
.note-detail-heading h3{
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.note-detail-kicker{
  display:flex;
  align-items:center;
  gap:6px;
  margin-bottom:3px;
  color:#6d4bc3;
  font-size:.68rem;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}
.note-detail-view{display:grid;gap:12px}
.note-detail-content{
  min-height:190px;
  max-height:min(52vh, 460px);
  padding:15px 16px;
  overflow:auto;
  overscroll-behavior:contain;
  border:1px solid rgba(208,213,221,.78);
  border-radius:13px;
  background:rgba(255,255,255,.76);
  color:var(--text);
  font-size:.9rem;
  line-height:1.65;
  white-space:pre-wrap;
  overflow-wrap:anywhere;
}
.note-detail-reminder-status{
  display:flex;
  align-items:center;
  gap:8px;
  padding:9px 11px;
  border:1px solid rgba(109,75,195,.18);
  border-radius:10px;
  background:rgba(196,181,253,.16);
  color:#5f3daf;
  font-size:.78rem;
  font-weight:700;
}
.note-detail-reminder-status.hide{display:none}
.note-detail-legacy-action{padding:2px 0}
.note-detail-actions{
  display:flex;
  align-items:center;
  gap:8px;
  margin-top:13px;
  padding-top:12px;
  border-top:1px solid var(--line);
}
.note-detail-actions .btn{display:inline-flex;align-items:center;justify-content:center;gap:6px}
.note-detail-actions .note-detail-delete-btn{color:var(--danger, #b42318)}
.note-detail-actions .note-detail-close-btn{margin-left:auto}
.note-delete-confirm{
  padding:15px;
  display:grid;
  grid-template-columns:auto 1fr;
  gap:11px;
  border:1px solid rgba(180,35,24,.2);
  border-radius:13px;
  background:rgba(254,243,242,.86);
}
.note-delete-confirm.hide{display:none}
.note-delete-confirm-icon{
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border-radius:10px;
  background:rgba(180,35,24,.1);
  color:var(--danger, #b42318);
}
.note-delete-confirm strong{display:block;color:var(--text);font-size:.9rem}
.note-delete-confirm p{margin:4px 0 0;color:var(--muted);font-size:.78rem;line-height:1.45}
.note-delete-confirm-actions{
  grid-column:1 / -1;
  display:flex;
  justify-content:flex-end;
  gap:8px;
