@media (prefers-reduced-motion:reduce){
  .wallet-logo-menu-dropdown[data-wallet-logo-portaled="true"],
  .note-workspace-modal .modal-dialog{animation:none}
  #notesList > .note-grid-card,
  .note-toggle-control,
  .note-toggle-control::after{transition:none}
}


/* ===== 20-themes-performance.css ===== */
/* Complete authenticated-workspace themes + lightweight async status controls. */
:root{
  --surface:#ffffff;
  --surface-elevated:#ffffff;
  --surface-soft:#ffffff;
  --surface-hover:#f8fbff;
  --surface-disabled:#f8fafc;
  --control-bg:#ffffff;
  --control-hover:#eef3fb;
  --surface-glass:rgba(255,255,255,.68);
  --surface-glass-strong:rgba(255,255,255,.82);
  --glass-highlight:rgba(255,255,255,.72);
  --glass-border:rgba(148,163,184,.20);
  --overlay-backdrop:rgba(15,23,42,.56);
  --on-primary:#ffffff;
  --focus-ring:rgba(36,87,214,.18);
}

html[data-triplem-theme="neon"]{
  --bg:#edfaff;--panel:rgba(248,253,255,.78);--panel-2:rgba(226,247,255,.60);
  --surface:rgba(251,254,255,.72);--surface-elevated:rgba(234,249,255,.64);--surface-soft:rgba(242,251,255,.56);--surface-hover:rgba(217,243,255,.64);--surface-disabled:rgba(231,243,248,.58);
  --control-bg:rgba(247,253,255,.68);--control-hover:rgba(220,245,255,.66);--surface-glass:rgba(248,253,255,.62);--surface-glass-strong:rgba(248,253,255,.78);--glass-highlight:rgba(255,255,255,.64);--glass-border:rgba(14,165,233,.14);--overlay-backdrop:rgba(4,35,50,.48);
  --text:#0c3447;--muted:#52778a;--line:rgba(2,132,199,.12);--line-strong:rgba(8,145,178,.25);
  --primary:#0284c7;--primary-soft:rgba(2,132,199,.13);--on-primary:#ffffff;
