/* The ambient circles live behind the workspace shell. Keep the theme color on
   body, but make the shell itself transparent so those circles can actually
   travel through the page and remain visible beneath glass surfaces. */
html[data-triplem-theme] body{
  background-color:var(--bg) !important;
}
html[data-triplem-theme] #app,
html[data-triplem-theme="default"] #app,
html[data-triplem-theme]:not([data-triplem-theme="default"]) #app{
  background-color:transparent !important;
  background-image:none !important;
}
html[data-triplem-theme] #app .panel{
  background:transparent !important;
}

/* Main section shells should refract the ambient circles rather than replace
   them with an opaque slab. Inputs, menus and data-critical controls remain
   stronger surfaces for readability. */
html[data-triplem-theme] #app :is(
  .card.section,.overview,.dashboard-block,.dashboard-hero-card,.dashboard-chart-card,
  .summary.currency-summary,.loan,.installment-plan-card,.asset-card,.dep-asset-card,
  .dep-summary-card,.expense-wallet-card,.expense-collapsible-section,.expense-item-row,
  .inventory-section-card,.inventory-sku-card,.inventory-draft-card,.note-card,.note-grid-card,
  #notesList > .card,.btc-wallet-card,.btc-wallet-details,.messages-compose-card,.messages-workspace
){
  background-color:color-mix(in srgb,var(--surface-glass) 86%,transparent) !important;
  background-image:linear-gradient(155deg,
    color-mix(in srgb,var(--surface-glass-strong) 88%,transparent),
    color-mix(in srgb,var(--surface-glass) 76%,transparent)) !important;
  backdrop-filter:blur(18px) saturate(1.10) !important;
  -webkit-backdrop-filter:blur(18px) saturate(1.10) !important;
}

/* The old title-glass pass used isolation:isolate. After the title plates were
   made transparent that isolation became unnecessary, and it trapped fixed
   dropdowns underneath later content. Remove the trap and raise the complete
   ownership chain whenever a menu is open. */
html[data-triplem-theme] #app :is(.section-head,.section-head-top,.title-group,.title-row){
  isolation:auto !important;
}
