  height:190px;
  right:-230px;
  top:50%;
  border-radius:50%;
  background:radial-gradient(circle,
    color-mix(in srgb,var(--tabs-lens-tint) 18%,transparent) 0%,
    color-mix(in srgb,var(--glass-highlight) 9%,transparent) 36%,
    transparent 70%);
  transform:translate3d(0,-50%,0);
  filter:blur(7px);
  opacity:.72;
  will-change:transform,opacity;
  animation:triplemTabsLensHalo 8.8s cubic-bezier(.22,.61,.36,1) infinite;
}
html[data-triplem-theme] #app > .tabs > .tab{
  position:relative;
  z-index:2;
  overflow:hidden;
  border:1px solid transparent;
  transition:background .2s ease,color .2s ease,transform .2s ease,box-shadow .2s ease,border-color .2s ease;
}
html[data-triplem-theme] #app > .tabs > .tab:hover:not(:disabled):not(.guest-disabled){
  border-color:color-mix(in srgb,var(--primary) 13%,transparent);
  box-shadow:inset 0 1px 0 color-mix(in srgb,var(--glass-highlight) 58%,transparent);
}
html[data-triplem-theme] #app > .tabs > .tab.active{
  border-color:color-mix(in srgb,var(--on-primary) 24%,transparent) !important;
  box-shadow:
    0 8px 20px color-mix(in srgb,var(--primary) 24%,transparent),
    inset 0 1px 0 color-mix(in srgb,var(--on-primary) 42%,transparent),
    inset 0 -1px 0 color-mix(in srgb,var(--primary) 38%,transparent) !important;
}
html[data-triplem-theme] #app > .tabs > .tab > i,
html[data-triplem-theme] #app > .tabs > .tab > .tab-label{
  position:relative;
  z-index:2;
}
html[data-triplem-theme] #app > .tabs > .tab.active::after{
  content:"";
  position:absolute;
  pointer-events:none;
  z-index:1;
  top:-70%;
  left:-24%;
  width:24%;
  height:240%;
  background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--on-primary) 48%,transparent),transparent);
  transform:translate3d(560%,0,0) rotate(13deg);
  filter:blur(1px);
  opacity:.62;
  animation:triplemActiveTabGlint 8.8s cubic-bezier(.22,.61,.36,1) infinite;
}

@keyframes triplemTabsLensSweep{
  0%,58%,100%{transform:translate3d(510%,0,0) rotate(13deg);opacity:0}
  63%{opacity:.22}
  72%{opacity:.86}
  84%{transform:translate3d(-145%,0,0) rotate(13deg);opacity:.28}
  88%{transform:translate3d(-165%,0,0) rotate(13deg);opacity:0}
}
@keyframes triplemTabsLensHalo{
  0%,58%,100%{transform:translate3d(0,-50%,0);opacity:0}
  66%{opacity:.58}
  84%{transform:translate3d(calc(-100vw - 260px),-50%,0);opacity:.20}
  88%{opacity:0}
}
@keyframes triplemActiveTabGlint{
  0%,62%,100%{transform:translate3d(560%,0,0) rotate(13deg);opacity:0}
  69%{opacity:.18}
  76%{opacity:.60}
  84%{transform:translate3d(-170%,0,0) rotate(13deg);opacity:0}
}

@media(max-width:820px){
  html[data-triplem-theme] #app > .tabs{
