/* ===== 21-public-security-parity.css ===== */
/* Triplem VIP public security-parity layer — 2026-09-04
   Visitor-facing only. Authenticated workspace appearance remains controlled by 07-theme.js. */

:root{
  --public-brand:#2457d6;
  --public-brand-dark:#1a3fa3;
  --public-brand-light:#3d6cf5;
  --public-navy:#071326;
  --public-navy-2:#0c1f3a;
  --public-gold:#f0a500;
  --public-ink:#111827;
  --public-muted:#667085;
  --public-line:rgba(36,87,214,.14);
  --public-glass:rgba(255,255,255,.78);
  --public-glass-strong:rgba(255,255,255,.92);
  --public-shadow:0 22px 60px rgba(18,48,105,.14);
}

/* ── Landing page: Security Architecture visual language ─────────────────── */
#lockScreen{
  --public-pointer-x:76%;
  --public-pointer-y:12%;
}
#lockScreen .landing-shell::before{
  content:"";
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:-1;
  background:
    radial-gradient(520px 360px at var(--public-pointer-x) var(--public-pointer-y),rgba(61,108,245,.11),transparent 70%),
    radial-gradient(460px 340px at 3% 88%,rgba(97,232,247,.08),transparent 72%);
}
#lockScreen .landing-nav{
  border-color:rgba(255,255,255,.76);
  background:linear-gradient(145deg,rgba(255,255,255,.84),rgba(244,248,255,.67));
  box-shadow:0 18px 52px rgba(18,48,105,.12),inset 0 1px 0 rgba(255,255,255,.92);
  backdrop-filter:blur(22px) saturate(1.25);
  -webkit-backdrop-filter:blur(22px) saturate(1.25);
}
#lockScreen .landing-nav-btn.is-active{
  color:var(--public-brand);
  border-color:rgba(36,87,214,.22);
  background:linear-gradient(145deg,rgba(36,87,214,.12),rgba(61,108,245,.06));
}
#lockScreen .landing-hero-marketing{
  position:relative;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.14);
  border-radius:30px;
  padding:clamp(30px,5vw,58px);
  background:
    radial-gradient(620px 360px at 94% 4%,rgba(61,108,245,.28),transparent 70%),
    radial-gradient(420px 280px at 4% 98%,rgba(97,232,247,.10),transparent 72%),
    linear-gradient(145deg,var(--public-navy),var(--public-navy-2) 58%,#102c53);
  box-shadow:0 34px 90px rgba(3,12,28,.28),inset 0 1px 0 rgba(255,255,255,.09);
}
#lockScreen .landing-hero-marketing::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background-image:repeating-linear-gradient(45deg,rgba(255,255,255,.012) 0,rgba(255,255,255,.012) 1px,transparent 1px,transparent 30px);
}
#lockScreen .landing-hero-marketing-inner,
#lockScreen .landing-hero-showcase{position:relative;z-index:1}
#lockScreen .landing-hero-marketing :is(.landing-eyebrow,.landing-hero-title,.landing-tagline,.landing-lead){color:#fff!important;-webkit-text-fill-color:initial!important}
#lockScreen .landing-hero-marketing .landing-lead{color:rgba(255,255,255,.72)!important}
#lockScreen .landing-hero-marketing .landing-eyebrow{
  display:inline-flex;
  align-items:center;
  gap:7px;
  padding:6px 10px;
  border:1px solid rgba(255,255,255,.13);
  border-radius:999px;
  background:rgba(255,255,255,.07);
  color:#b9d2ff!important;
}
#lockScreen .landing-hero-marketing .landing-hero-trust{color:rgba(255,255,255,.74)!important}
#lockScreen .landing-hero-marketing .landing-hero-trust i{color:#9cc0ff}
#lockScreen .landing-showcase-window{
  border-color:rgba(255,255,255,.15)!important;
  background:linear-gradient(150deg,rgba(255,255,255,.12),rgba(255,255,255,.055))!important;
  color:#fff!important;
  box-shadow:0 24px 70px rgba(0,0,0,.25),inset 0 1px 0 rgba(255,255,255,.10)!important;
  backdrop-filter:blur(16px) saturate(1.14);
  -webkit-backdrop-filter:blur(16px) saturate(1.14);
}
#lockScreen .landing-showcase-window :is(strong,b,span){color:inherit}
#lockScreen .landing-showcase-window :is(small,.landing-showcase-ledger-head span){color:rgba(255,255,255,.58)!important}
#lockScreen .landing-showcase-row,
#lockScreen .landing-showcase-metrics article{border-color:rgba(255,255,255,.10)!important;background:rgba(255,255,255,.055)!important}
#lockScreen .landing-showcase-note{color:rgba(255,255,255,.55)!important}

/* The primary free-signup CTA is intentionally unmistakable. */
#lockScreen #landingHeroTrialBtn,
#lockScreen .landing-trial-banner-actions .landing-cta-pulse{
  position:relative;
  isolation:isolate;
  min-height:54px;
  padding:14px 24px!important;
  border:1px solid rgba(255,255,255,.34)!important;
  border-radius:16px!important;
  background:linear-gradient(135deg,#ffffff 0%,#e9f1ff 46%,#bcd0ff 100%)!important;
  color:#12357f!important;
  font-size:1rem!important;
  font-weight:950!important;
  letter-spacing:-.015em;
  box-shadow:0 18px 42px rgba(72,123,244,.32),0 0 0 5px rgba(255,255,255,.07),inset 0 1px 0 #fff!important;
  transform:translateZ(0);
  overflow:hidden;
}
#lockScreen #landingHeroTrialBtn::after,
#lockScreen .landing-trial-banner-actions .landing-cta-pulse::after{
  content:"";
  position:absolute;
  inset:-20% -55%;
  z-index:-1;
  background:linear-gradient(105deg,transparent 38%,rgba(255,255,255,.94) 50%,transparent 62%);
  transform:translateX(-50%) skewX(-14deg);
  animation:publicSignupShine 3.8s ease-in-out infinite;
}
#lockScreen #landingHeroTrialBtn:hover,
#lockScreen .landing-trial-banner-actions .landing-cta-pulse:hover{
  transform:translateY(-2px) scale(1.015);
  box-shadow:0 24px 54px rgba(72,123,244,.38),0 0 0 6px rgba(255,255,255,.09)!important;
}
#lockScreen #landingHeroTrialBtn :is(i,span),
#lockScreen .landing-trial-banner-actions .landing-cta-pulse :is(i,span){color:#12357f!important;-webkit-text-fill-color:#12357f!important}
@keyframes publicSignupShine{
  0%,55%{transform:translateX(-50%) skewX(-14deg);opacity:0}
  62%{opacity:.75}
  82%{transform:translateX(52%) skewX(-14deg);opacity:.18}
  100%{transform:translateX(62%) skewX(-14deg);opacity:0}
}

#lockScreen :is(.landing-trial-banner,.landing-seo-pillar,.landing-surface-card,.landing-info-action){
  border-color:rgba(255,255,255,.78)!important;
  background:linear-gradient(155deg,rgba(255,255,255,.87),rgba(246,249,255,.68))!important;
  box-shadow:var(--public-shadow),inset 0 1px 0 rgba(255,255,255,.92)!important;
  backdrop-filter:blur(16px) saturate(1.12);
  -webkit-backdrop-filter:blur(16px) saturate(1.12);
}
#lockScreen .landing-seo-pillar{
  background:
    radial-gradient(520px 260px at 100% 0,rgba(61,108,245,.11),transparent 72%),
    linear-gradient(155deg,rgba(255,255,255,.88),rgba(243,248,255,.70))!important;
}
#lockScreen .landing-seo-card{
  border:1px solid rgba(36,87,214,.10)!important;
  background:linear-gradient(150deg,rgba(255,255,255,.94),rgba(241,247,255,.74))!important;
  transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease;
}
#lockScreen .landing-seo-card:hover{transform:translateY(-3px);border-color:rgba(36,87,214,.25)!important;box-shadow:0 18px 38px rgba(36,87,214,.12)!important}

/* ── Visitor notification control ───────────────────────────────────────── */
.landing-visitor-alert-control{
  display:inline-flex;
  align-items:center;
  gap:7px;
  height:38px;
  padding:4px 8px 4px 10px;
  border:1px solid rgba(36,87,214,.13);
  border-radius:999px;
  background:rgba(255,255,255,.70);
  box-shadow:0 8px 20px rgba(36,87,214,.08);
